// ACCT1102 400-question practice bank, transcribed from the user's own lecture-slide
// practice bank PDF (Topics 1-4). Loaded as a plain global before the main app script.
// type: 'mcq' (opts + ans index), 'tf' (ans boolean), 'calc'/'table'/'short' (reveal-style,
// self-marked, since these have multi-part or free-form answers that aren't safely
// auto-gradable at this scale).
const QUIZ_BANK_PARTS = [
  {id:1, title:'Topic 1: Management and Cost Accounting', range:[1,100]},
  {id:2, title:'Topic 2: Overhead and Job Costing', range:[101,200]},
  {id:3, title:'Topic 3: Cost-Volume-Profit (CVP) Analysis', range:[201,300]},
  {id:4, title:'Topic 4: Budgets & Responsibility Accounting', range:[301,400]},
];
const QUIZ_BANK = [
{id:1,part:1,type:'mcq',q:"Who is the course coordinator, lecturer and tutor for ACCT1102?",opts:["Binhui Hu","June Jung","Chris Zhang","Robert Ferguson"],ans:1,exp:"June Jung is listed as Course Coordinator/Lecturer/Tutor."},
{id:2,part:1,type:'mcq',q:"How is ACCT1102 delivered?",opts:["A one-hour lecture and a three-hour tutorial (Week 1)","A two-hour lecture and a two-hour tutorial (tutorials begin Week 2)","A two-hour lecture only; tutorials are online and optional","A three-hour workshop with no separate tutorial"],ans:1,exp:"Two-hour lecture, two-hour tutorial beginning from Week 2."},
{id:3,part:1,type:'mcq',q:"How many students must be in each group for the Budget Preparation group assignment?",opts:["Two to three","Three to five","Exactly five","Exactly four"],ans:3,exp:"Groups must have FOUR students - no more, no less."},
{id:4,part:1,type:'tf',q:"A peer assessment task must be completed in addition to the group assignment report.",ans:true,exp:"The group assignment (Business Report on Budget Preparation) has a peer assessment component."},
{id:5,part:1,type:'mcq',q:"Group registration (via Blackboard) is due:",opts:["Friday 9 October, 1pm (Week 10)","Tuesday 8 September, 9am (Week 7)","Friday 16 October, 6pm (Week 11)","Friday 28 August, 6pm (Week 5)"],ans:3,exp:"Registration Fri 28 Aug 6pm; materials released Tue 8 Sep 9am; submission Fri 9 Oct 1pm; peer assessment Fri 16 Oct 6pm."},
{id:6,part:1,type:'mcq',q:"The group assignment submission is due:",opts:["Friday 28 August, 6pm (Week 5)","Tuesday 8 September, 9am (Week 7)","Friday 9 October, 1pm (Week 10)","Friday 16 October, 6pm (Week 11)"],ans:2,exp:"Submission is Friday 9 October at 1pm; the peer assessment is due a week later."},
{id:7,part:1,type:'short',q:"List the five learning objectives of ACCT1102.",exp:"(1) Understand the roles of management and cost accounting. (2) Use costing and budgeting processes and analysis. (3) Work in a group to prepare and professionally communicate a budget. (4) Apply a basic understanding of performance measurement and balanced scorecards. (5) Apply professional standards to understand accounting ethics."},
{id:8,part:1,type:'mcq',q:"The prescribed textbook is:",opts:["Horngren, Introduction to Financial Accounting (11th ed.)","Kaplan & Norton, The Balanced Scorecard","Datar & Rajan, Horngren's Cost Accounting: A Managerial Emphasis (17th Global Edition)","Drury, Management and Cost Accounting (10th ed.)"],ans:2,exp:"Datar & Rajan, Horngren's Cost Accounting: A Managerial Emphasis (17th Global Edition)."},
{id:9,part:1,type:'short',q:"State the Horngren textbook chapters set as reading for Topics 1, 2, 3 and 4.",exp:"Topic 1: Ch. 1 & 2. Topic 2: Ch. 4. Topic 3: Ch. 3. Topic 4: Ch. 6 (incl. Appendix)."},
{id:10,part:1,type:'mcq',q:"Which one of these is Topic 8 in the ACCT1102 course outline?",opts:["Variance Analysis","Traditional Overhead Allocation","Budgets: Financial Statements and Cash","Strategy, Balanced Scorecard & Sustainability"],ans:1,exp:"Order: 1 Mgmt & Cost Acc; 2 Overhead & Job Costing; 3 CVP; 4 Intro to Budgets & Resp. Acc; 5 Operating Budgets; 6 Budgets: FS & Cash; 7 Budgets incl. Group Assignment; 8 Traditional OH Allocation; 9 Variance Analysis; 10 Performance Measurement & Compensation; 11 Strategy, BSC & Sustainability; 12 Ethics; 13 Revision."},
{id:11,part:1,type:'mcq',q:"Where can you get help with course questions outside lectures and tutorials?",opts:["Attend a staff consultation (from Week 2) or post on Ed Discussion on the course Blackboard site","Only by emailing the Dean of Business","Consultations run only in the exam period","Questions are not permitted outside tutorials"],ans:0,exp:"Regular consultations run during teaching weeks from Week 2; questions can also be posted to Ed Discussion on Blackboard."},
{id:12,part:1,type:'mcq',q:"Management accounting is best described as measuring and reporting:",opts:["financial and non-financial information that helps managers fulfil the organisation's goals","only financial information for external investors","only historical information prepared under GAAP","tax information for the tax office"],ans:0,exp:"Definition given in the lecture."},
{id:13,part:1,type:'mcq',q:"Financial accounting is mainly concerned with:",opts:["external reporting guided by generally accepted accounting principles","internal decision-making with no prescribed rules","hourly operational reports for supervisors","budgets for individual departments"],ans:0,exp:"Definition given in the lecture."},
{id:14,part:1,type:'mcq',q:"(Quick Check 1) Management accounting:",opts:["is strictly bound by AASB standards","is only relevant for external stakeholders","is boring","none of the above"],ans:3,exp:"MA has no prescribed rules and serves INTERNAL users, so (a) and (b) are wrong; (c) is an opinion, not a fact from the lecture."},
{id:15,part:1,type:'mcq',q:"The primary users of management accounting information are:",opts:["investors","banks and lenders","managers inside the organisation","regulators such as ASIC"],ans:2,exp:"External users (investors, banks, regulators, suppliers) use financial accounting."},
{id:16,part:1,type:'mcq',q:"Management accounting is generally ___-oriented while financial accounting is generally ___-oriented.",opts:["future; past","past; future","past; past","future; future"],ans:0,exp:"MA: future-oriented (budgets). FA: past-oriented historical information."},
{id:17,part:1,type:'tf',q:"Financial accounting reports are based on GAAP, the Corporations Act and ASIC requirements, and in some cases are certified by an external auditor.",ans:true,exp:"Rules of measurement and reporting for FA."},
{id:18,part:1,type:'tf',q:"Management accounting reports must follow a fixed set of prescribed rules like the accounting standards.",ans:false,exp:"MA has no prescribed rules ('subjective'); it is normally based on cost-benefit analysis."},
{id:19,part:1,type:'mcq',q:"Which rule normally governs the design of management accounting reports?",opts:["AASB accounting standards","The Corporations Act","Cost-benefit analysis","ASIC disclosure rules"],ans:2,exp:"MA has no prescribed rules; cost-benefit analysis applies."},
{id:20,part:1,type:'mcq',q:"The time span covered by management accounting information ranges from:",opts:["monthly reports to 3 years","hourly information to 15-20 years","annual reports only","quarterly reports only"],ans:1,exp:"FA reports are annual and quarterly; MA can be hourly through to 15-20 years."},
{id:21,part:1,type:'tf',q:"Management accounting reports are designed to influence the behaviour of managers and employees.",ans:true,exp:"MA is designed to influence behaviour; FA only influences behaviour indirectly."},
{id:22,part:1,type:'tf',q:"Management accounting and financial accounting are completely unrelated activities.",ans:false,exp:"The lecture stresses that they are linked (e.g. product costs from MA feed inventory and COGS in the FS)."},
{id:23,part:1,type:'table',q:"Complete the comparison of management accounting (MA) and financial accounting (FA): Primary users, Time focus, Rules of reporting, Scope of reports, Behavioural implications.",exp:"MA: internal managers; future-oriented; no prescribed rules (cost-benefit); products/departments/territories/strategies; designed to influence behaviour. FA: external users (investors, banks, regulators, suppliers); past-oriented; GAAP/Corporations Act/ASIC, sometimes audited; company as a whole (annual/quarterly); may influence behaviour if pay is based on FS."},
{id:24,part:1,type:'short',q:"Explain three differences between management accounting and financial accounting.",exp:"Any three of: users (internal vs external); time orientation (future vs past); rules (none/cost-benefit vs GAAP, Corporations Act, ASIC, audit); time span and report type (hourly to 20 yrs, by product/department vs annual/quarterly for whole company); purpose (help managers achieve goals vs help external users decide); behavioural influence (designed to influence vs incidental)."},
{id:25,part:1,type:'mcq',q:"Which management accounting system is used to estimate the costs of goods and services, activities and departments?",opts:["Budgeting system","Cost accounting system","Performance measurement system","Cost management system"],ans:1,exp:"Cost accounting system."},
{id:26,part:1,type:'mcq',q:"Which system monitors financial and non-financial performance (quality, environmental, innovation) by tracking actual performance against budgeted targets?",opts:["Cost accounting system","Budgeting system","Cost management system","Performance measurement system"],ans:3,exp:"Performance measurement system."},
{id:27,part:1,type:'mcq',q:"Which system provides information to actively manage resources and increase organisational value?",opts:["Cost accounting system","Cost management system","Budgeting system","Performance measurement system"],ans:1,exp:"Cost management system."},
{id:28,part:1,type:'table',q:"Name the management accounting system described: (1) estimates costs of goods/services/activities/departments; (2) estimates revenues and costs for organisational units; (3) tracks actual results against budgeted targets; (4) provides information to manage resources and increase organisational value.",exp:"(1) Cost accounting system. (2) Budgeting system. (3) Performance measurement system. (4) Cost management system."},
{id:29,part:1,type:'short',q:"Name the elements of the control cycle shown in the lecture.",exp:"Strategy -> Planning (budgeting & forecasting) -> Coordination & Monitoring -> Evaluation -> feedback into future planning (the 'cycle')."},
{id:30,part:1,type:'mcq',q:"Feedback in the control cycle involves:",opts:["examining past performance and systematically exploring alternative ways to improve future performance","preparing statutory financial statements","auditing the annual report","preparing the master budget for the first time"],ans:0,exp:"Feedback is what creates the 'cycle'."},
{id:31,part:1,type:'mcq',q:"Which is NOT a listed use of feedback in the control cycle?",opts:["Changing targets and goals","Searching for new methods of operating","Adjusting the reward and compensation system","Eliminating the need for future planning"],ans:3,exp:"Other listed uses include revising predictions about the future."},
{id:32,part:1,type:'tf',q:"The control cycle represents the traditional uses of management accounting information.",ans:true,exp:"Contemporary roles (problem solving, attention directing, resource management) extend it."},
{id:33,part:1,type:'mcq',q:"A manager compares the costs of leasing versus buying equipment. This is an example of:",opts:["attention directing","resource management","problem solving","financial reporting"],ans:2,exp:"Problem solving = comparative analysis to identify the best alternative."},
{id:34,part:1,type:'mcq',q:"A KPI dashboard highlights that customer complaints are rising so managers can focus on it. This is:",opts:["problem solving","resource management","attention directing","cost accumulation"],ans:2,exp:"Attention directing makes opportunities and problems visible."},
{id:35,part:1,type:'mcq',q:"Analysing the drivers of customer value, shareholder wealth and organisational innovation - not just cost reduction - is:",opts:["resource management","problem solving","attention directing","cost tracing"],ans:0,exp:"Resource management = effective and efficient use of all resources."},
{id:36,part:1,type:'mcq',q:"Deciding whether to outsource a department or which product mix to make is an example of:",opts:["attention directing","resource management","problem solving","budget slack"],ans:2,exp:"Problem solving."},
{id:37,part:1,type:'short',q:"Explain the three contemporary roles of management accounting, giving an example of each.",exp:"Problem solving: comparative analysis to choose the best alternative (lease vs buy, outsource, product mix). Attention directing: making opportunities and problems visible (Balanced Scorecard, KPI dashboards). Resource management: effective and efficient use of all resources, analysing drivers of customer value, stakeholder wealth and innovation, not just cost reduction."},
{id:38,part:1,type:'mcq',q:"A cost is defined as:",opts:["the monetary value of resources sacrificed or forgone to achieve a specific objective","the price paid to suppliers only","the amount recorded as an asset","any expense in the income statement"],ans:0,exp:"Definition given in the lecture."},
{id:39,part:1,type:'mcq',q:"A cost object is:",opts:["any cost that varies with volume","anything for which a cost measurement is desired","an indirect cost","a cost that cannot be traced"],ans:1,exp:"E.g. a product, job, department, customer."},
{id:40,part:1,type:'mcq',q:"Direct costs are costs that:",opts:["are always fixed","are related to a cost object but cannot be traced easily","are related to a cost object and can be traced to it easily and economically","are always period costs"],ans:2,exp:"Definition given in the lecture."},
{id:41,part:1,type:'mcq',q:"Indirect costs (overheads) are:",opts:["traced to the cost object using measured quantities","always variable","only found in service firms","related to a cost object but cannot be traced to it easily and economically, so they are allocated"],ans:3,exp:"Definition given in the lecture."},
{id:42,part:1,type:'mcq',q:"Variable costs are costs that:",opts:["remain the same in total across wide changes in volume","change per unit but not in total","are never controllable","change in total in proportion to changes in volume"],ans:3,exp:"Definition given in the lecture."},
{id:43,part:1,type:'mcq',q:"Fixed costs are costs that:",opts:["change in total in proportion to volume","remain unchanged in total for a given period despite wide changes in volume","are the same per unit at all volumes","are always indirect"],ans:1,exp:"Definition given in the lecture."},
{id:44,part:1,type:'mcq',q:"Inventoriable costs are:",opts:["all costs expensed immediately in the period incurred","only selling and administration costs","costs of R&D only","product costs treated as assets when incurred and expensed as COGS only when the product is sold"],ans:3,exp:"Definition given in the lecture."},
{id:45,part:1,type:'mcq',q:"Period costs are:",opts:["all costs in the income statement other than cost of goods sold","costs held in inventory on the balance sheet","the costs of direct materials","costs of finished goods not yet sold"],ans:0,exp:"Definition given in the lecture."},
{id:46,part:1,type:'tf',q:"Marketing and administration expenses are inventoriable costs.",ans:false,exp:"They are period costs expensed in the period incurred."},
{id:47,part:1,type:'mcq',q:"Which of the following is an example of a direct cost of a manufactured chair?",opts:["Factory rent","Depreciation of the factory building","Timber used to make the chair","Salary of the factory manager"],ans:2,exp:"Timber can be traced easily and economically to the chair."},
{id:48,part:1,type:'mcq',q:"Which of the following is inventoriable for a manufacturer?",opts:["CEO's salary at head office","Factory supervisor's salary","Sales commissions","Advertising"],ans:1,exp:"Factory overhead is a manufacturing (product) cost; the others are period costs."},
{id:49,part:1,type:'table',q:"A furniture manufacturer is costing tables (cost object = a table). Classify: Timber used in tables; Factory rent; Sales staff commissions; Assembly-line worker wages; Head-office CEO salary; Depreciation of factory machinery; Glue and cleaning supplies; Advertising campaign (manufacturing?/direct-indirect/inventoriable-period).",exp:"Timber: Mfg, Direct, Inventoriable. Factory rent: Mfg, Indirect, Inventoriable. Sales commissions: Non-mfg, n/a, Period. Assembly wages: Mfg, Direct, Inventoriable. CEO salary: Non-mfg, n/a, Period. Machinery depreciation: Mfg, Indirect, Inventoriable. Glue/cleaning: Mfg, Indirect, Inventoriable. Advertising: Non-mfg, n/a, Period."},
{id:50,part:1,type:'table',q:"An automotive manufacturer has cost object = a car. Classify (direct/indirect, inventoriable/period): Steel for car bodies; Salary of plant maintenance staff; Electricity for factory; R&D expense; Distribution costs to customers; Wages of paint-shop worker on a specific car.",exp:"Steel: Direct, Inventoriable. Maintenance staff: Indirect, Inventoriable. Electricity: Indirect, Inventoriable. R&D: n/a, Period. Distribution: n/a, Period. Paint-shop wages on a specific car: Direct, Inventoriable."},
{id:51,part:1,type:'mcq',q:"Direct/indirect classification is about ___, whereas variable/fixed classification is about ___.",opts:["traceability to a cost object; cost behaviour as volume changes","cost behaviour; traceability","timing of expensing; traceability","controllability; timing of expensing"],ans:0,exp:"See summary of cost classifications."},
{id:52,part:1,type:'short',q:"What are the three categories of manufacturing costs? What does manufacturing overhead include?",exp:"Direct materials (DM), direct labour (DL) and manufacturing overhead (MOH). MOH includes indirect materials, indirect labour and other indirect manufacturing costs (rent, depreciation, utilities...)."},
{id:53,part:1,type:'mcq',q:"Prime costs comprise:",opts:["DL + MOH","DM + MOH","DM + DL","DM + DL + MOH"],ans:2,exp:"Prime cost = DM + DL."},
{id:54,part:1,type:'mcq',q:"Conversion costs comprise:",opts:["DM + DL","DM + MOH","DL + MOH","DM + DL + MOH"],ans:2,exp:"Conversion = costs of transforming materials into finished goods = DL + MOH."},
{id:55,part:1,type:'mcq',q:"Which manufacturing cost is included in BOTH prime cost and conversion cost?",opts:["Direct labour","Direct materials","Manufacturing overhead","Selling expenses"],ans:0,exp:"DL is in prime (DM+DL) and conversion (DL+MOH)."},
{id:56,part:1,type:'mcq',q:"Which cost is included in NEITHER prime cost NOR conversion cost?",opts:["Direct materials","Direct labour","Indirect labour","Sales commissions"],ans:3,exp:"Sales commissions are non-manufacturing (period) costs."},
{id:57,part:1,type:'calc',q:"(Lecture Q1) A product has direct material $20, direct labour $24 and factory overhead $30 per unit. Calculate (a) unit manufacturing cost, (b) prime cost, (c) conversion cost.",exp:"(a) $74 (b) $44 (c) $54. 20+24+30=74; Prime=DM+DL=20+24=44; Conversion=DL+MOH=24+30=54."},
{id:58,part:1,type:'calc',q:"(Lecture Q2) Conversion costs are 60% of the unit manufacturing cost of $40.00. Direct labour is 40% of prime cost. Find the unit cost of direct materials, direct labour and factory overhead.",exp:"DM = $16.00; DL = $10.67; FOH = $13.33. Conversion = 0.6x40 = 24.00, so DM = 40-24.00 = 16.00. Prime = 16.00/0.6 = 26.67; DL = 0.4x26.67 = 10.67. FOH = 24.00-10.67 = 13.33."},
{id:59,part:1,type:'calc',q:"A firm's direct materials are $8.00, direct labour $6.50 and manufacturing overhead $9.25 per unit. What are (a) prime cost and (b) conversion cost per unit?",exp:"(a) $14.50 (b) $15.75. Prime = 8.00+6.50 = 14.50. Conversion = 6.50+9.25 = 15.75."},
{id:60,part:1,type:'calc',q:"In a month a manufacturer used $180,000 of direct materials, $120,000 direct labour and incurred $150,000 manufacturing overhead. Compute prime costs, conversion costs and total manufacturing costs.",exp:"Prime $300,000; conversion $270,000; total $450,000."},
{id:61,part:1,type:'calc',q:"Prime cost per unit is $35 and conversion cost per unit is $40. Direct labour is $15 per unit. Find DM, MOH and total manufacturing cost per unit.",exp:"DM $20; MOH $25; total $60. DM = prime-DL = 35-15 = 20. MOH = conversion-DL = 40-15 = 25. Total = 20+15+25 = 60."},
{id:62,part:1,type:'mcq',q:"Total manufacturing cost per unit equals:",opts:["prime cost + manufacturing overhead","prime cost + conversion cost","conversion cost + selling costs","direct materials + conversion cost + period costs"],ans:0,exp:"Prime + MOH = DM+DL+MOH. (Prime+conversion would double count DL.)"},
{id:63,part:1,type:'table',q:"A firm incurred: direct materials $45,000; direct labour $30,000; factory rent $12,000; indirect labour $8,000; sales salaries $15,000; factory utilities $5,000. Find Prime cost, Manufacturing overhead, Conversion cost, Total manufacturing cost, Period cost.",exp:"Prime cost 75,000; Manufacturing overhead 25,000; Conversion cost 55,000; Total manufacturing cost 100,000; Period cost 15,000 (sales salaries)."},
{id:64,part:1,type:'mcq',q:"Which is NOT one of the three main industry sectors for management accounting?",opts:["Services","Merchandising","Manufacturing","Agricultural"],ans:3,exp:"The three sectors are services, merchandising and manufacturing."},
{id:65,part:1,type:'mcq',q:"Merchandising companies:",opts:["convert materials into finished goods","buy tangible products and sell them without changing their basic form","provide intangible services with no inventory","hold raw materials, WIP and finished goods"],ans:1,exp:"Definition given in the lecture."},
{id:66,part:1,type:'mcq',q:"How many inventory accounts does a merchandiser typically have on its balance sheet?",opts:["Two","One (merchandise inventory)","Three","None"],ans:1,exp:"A manufacturer has three: raw materials, work in process and finished goods."},
{id:67,part:1,type:'mcq',q:"A typical manufacturer holds which three inventory accounts?",opts:["Raw materials, work in process, finished goods","Raw materials, merchandise inventory, finished goods","Work in process, merchandise inventory, cost of goods sold","Direct materials, indirect materials, supplies"],ans:0,exp:"Standard manufacturer inventory accounts."},
{id:68,part:1,type:'mcq',q:"Raw materials inventory is best described as:",opts:["goods partially worked on but not completed","goods completed but not yet sold","materials in stock that will be used in the manufacturing process","goods purchased for resale"],ans:2,exp:"Definition given in the lecture."},
{id:69,part:1,type:'mcq',q:"Work in process inventory is best described as:",opts:["goods partially worked on but not yet completed","materials in stock","goods completed but not yet sold","goods purchased for resale"],ans:0,exp:"Definition given in the lecture."},
{id:70,part:1,type:'mcq',q:"Finished goods inventory is best described as:",opts:["goods partially completed","goods completed but not yet sold","materials waiting to be used","costs of goods sold this period"],ans:1,exp:"Definition given in the lecture."},
{id:71,part:1,type:'mcq',q:"Merchandise inventory includes:",opts:["only the supplier's invoice price with no other costs","raw materials and WIP","the cost of goods purchased for resale plus costs of bringing them to their present location and condition","period costs such as advertising"],ans:2,exp:"Definition given in the lecture."},
{id:72,part:1,type:'table',q:"(Quick Check 2) Classify each into its industry sector: Kmart; University of Queensland; Toyota; PwC; Dan Murphy's; Stone & Wood Brewing Co.",exp:"Kmart: Merchandising. UQ: Services. Toyota: Manufacturing. PwC: Services. Dan Murphy's: Merchandising. Stone & Wood: Manufacturing."},
{id:73,part:1,type:'table',q:"Classify each business by sector and state which inventory account(s) it would hold: A hair salon; A shoe retailer buying finished shoes; A bakery baking bread from flour; A law firm; A supermarket.",exp:"Hair salon: Services, none. Shoe retailer: Merchandising, merchandise inventory. Bakery: Manufacturing, RM/WIP/FG. Law firm: Services, none. Supermarket: Merchandising, merchandise inventory."},
{id:74,part:1,type:'mcq',q:"Raw materials used equals:",opts:["Opening RM - Purchases + Closing RM","Opening RM + Closing RM - Purchases","Purchases - Opening RM - Closing RM","Opening RM + Purchases - Closing RM"],ans:3,exp:"Standard raw materials roll-forward formula."},
{id:75,part:1,type:'mcq',q:"Cost of goods manufactured (COGM) equals:",opts:["Opening FG + Total manufacturing costs - Closing FG","Opening WIP + COGS - Closing WIP","DM used + DL only","Opening WIP + Total manufacturing costs incurred - Closing WIP"],ans:3,exp:"Standard COGM formula."},
{id:76,part:1,type:'mcq',q:"Cost of goods sold (COGS) equals:",opts:["Opening FG + COGM - Closing FG","Opening WIP + COGM - Closing WIP","Opening FG + Purchases - Closing FG","Opening RM + COGM - Closing RM"],ans:0,exp:"Standard COGS formula."},
{id:77,part:1,type:'mcq',q:"Which items are added to the Work in Process account during the period?",opts:["Purchases of raw materials, selling costs and admin costs","COGS and closing FG","Direct materials used, direct labour and applied manufacturing overhead","Only direct materials"],ans:2,exp:"WIP accumulates DM used, DL and applied MOH."},
{id:78,part:1,type:'mcq',q:"In the costing-system diagram, indirect materials and indirect labour flow to:",opts:["Work in process","Overheads","Finished goods","Cost of goods sold"],ans:1,exp:"Then overheads are added to WIP."},
{id:79,part:1,type:'mcq',q:"Which is the correct order of the profit & loss items?",opts:["Revenue - Period expenses = Gross profit; Gross profit - COGS = Profit","Revenue + COGS = Gross profit","Revenue - COGS - Gross profit = Period expenses","Revenue - COGS = Gross profit; Gross profit - Period expenses = Profit"],ans:3,exp:"Standard income statement flow."},
{id:80,part:1,type:'tf',q:"Only when a product is sold does its manufacturing cost move from Finished Goods inventory on the balance sheet to COGS in the profit & loss.",ans:true,exp:"Inventoriable costs become COGS only when sold."},
{id:81,part:1,type:'calc',q:"Opening raw materials $40,000; purchases $155,000; closing raw materials $35,000. Find raw materials used.",exp:"$160,000. 40,000+155,000-35,000=160,000."},
{id:82,part:1,type:'calc',q:"Opening WIP $22,000; total manufacturing costs incurred $310,000; closing WIP $30,000. Find COGM.",exp:"$302,000. 22,000+310,000-30,000=302,000."},
{id:83,part:1,type:'calc',q:"Opening FG $48,000; COGM $302,000; closing FG $50,000. Find COGS.",exp:"$300,000. 48,000+302,000-50,000=300,000."},
{id:84,part:1,type:'calc',q:"COGM was $850,000, opening WIP $45,000 and closing WIP $60,000. Direct materials used were $300,000 and direct labour $250,000. Find manufacturing overhead.",exp:"$315,000. Total mfg costs = 850,000+60,000-45,000=865,000. MOH=865,000-300,000-250,000=315,000."},
{id:85,part:1,type:'calc',q:"COGS was $620,000, closing FG $75,000 and opening FG $90,000. Find COGM.",exp:"$605,000. COGM=620,000+75,000-90,000=605,000."},
{id:86,part:1,type:'calc',q:"A firm's raw materials used were $210,000. Opening RM was $25,000 and closing RM $32,000. How much material was purchased?",exp:"$217,000. Purchases = 210,000+32,000-25,000=217,000."},
{id:87,part:1,type:'table',q:"(Quick Check 3) Determine the missing amount for each case: Case A (Beginning FG 120,000, COGM 400,000, Ending FG 40,000, COGS ?); Case B (Beginning FG ?, COGM 960,000, Ending FG 160,000, COGS 1,000,000); Case C (Beginning FG 7,000, COGM ?, Ending FG 25,000, COGS 280,000).",exp:"Case A COGS = 480,000. Case B Beginning FG = 200,000. Case C COGM = 298,000. (Beginning FG + COGM - Ending FG = COGS)"},
{id:88,part:1,type:'short',q:"(Quick Check 3 part ii) Explain the components of cost of goods manufactured (COGM).",exp:"COGM = opening WIP + total manufacturing costs incurred in the period (direct materials used + direct labour + manufacturing overhead) - closing WIP. It is the cost of all goods completed and transferred from WIP to finished goods in the period."},
{id:89,part:1,type:'table',q:"Complete the missing inventory figures: Case D (Beginning RM 30,000, Purchases 95,000, Ending RM 25,000, Used ?); Case E (Beginning RM ?, Purchases 70,000, Ending RM 12,000, Used 76,000).",exp:"Case D Used = 100,000. Case E Beginning = 18,000."},
{id:90,part:1,type:'table',q:"Complete the WIP and finished goods roll-forward: Opening WIP 60,000, Total mfg costs incurred 410,000, Closing WIP 55,000, COGM ?; Opening FG 80,000, Closing FG 70,000, COGS ?.",exp:"COGM = 415,000. COGS = 425,000."},
{id:91,part:1,type:'table',q:"(Lecture Q3, part 1) Materials inventory: Beginning 105, Purchases 365, Available ?, Used 385, Ending ?; Direct labour ?, Variable OH 265, Fixed OH (actual) ?, Total MOH 450, Total mfg costs incurred 1,610.",exp:"Available = 470. Ending = 85. Fixed MOH = 185. Direct labour = 775."},
{id:92,part:1,type:'table',q:"(Lecture Q3, part 2) WIP: Beginning 230, Mfg costs incurred ?, Available ?, COGM 1,660, Ending ?; FG: Beginning 130, COGM 1,660, Available for sale ?, COGS (actual fixed MOH) ?, Ending 101.",exp:"Mfg costs incurred = 1,610. Available (WIP) = 1,840. Ending WIP = 180. Available for sale (FG) = 1,790. COGS = 1,689."},
{id:93,part:1,type:'table',q:"(Lecture Q3, part 3) Revenue 2,501, COGS ?, Gross profit ?, Period costs ?, Profit before tax 510; Inventories beginning 465, ending ?.",exp:"COGS=1,689. GP=812. Period costs=302. Ending inventories=366."},
{id:94,part:1,type:'table',q:"Prepare Pinnacle Cabinets' Schedule of COGM: opening/closing RM $30,000/$25,000; RM purchases $120,000; direct labour $90,000; indirect materials $8,000; indirect labour $22,000; factory depreciation $30,000; factory utilities $15,000; opening/closing WIP $40,000/$35,000.",exp:"DM used=125,000. MOH=75,000. Total mfg costs=290,000. COGM=295,000."},
{id:95,part:1,type:'table',q:"Using COGM $295,000, prepare Pinnacle Cabinets' Schedule of COGS and income statement: opening/closing FG $60,000/$55,000; revenue $480,000; selling $40,000; admin $30,000.",exp:"COGS=300,000. GP=180,000. Profit before tax=110,000 (period costs 70,000)."},
{id:96,part:1,type:'calc',q:"For Pinnacle Cabinets, what is the value of total inventories (RM+WIP+FG) on the closing balance sheet, and by how much did total inventories change?",exp:"Closing $115,000; a decrease of $15,000. Closing=25,000+35,000+55,000=115,000; Opening=130,000."},
{id:97,part:1,type:'table',q:"Harbour Boats: Direct materials used 210,000; Direct labour 140,000; MOH 175,000; Total mfg costs ?; Opening WIP 35,000; Closing WIP 20,000; COGM ?; Opening FG 50,000; Closing FG 65,000; COGS ?; Revenue 760,000; Gross profit ?; Period costs 150,000; Profit before tax ?.",exp:"Total mfg=525,000. COGM=540,000. COGS=525,000. GP=235,000. Profit=85,000."},
{id:98,part:1,type:'calc',q:"Merchandiser: opening inventory $18,000, purchases $92,000, closing inventory $21,000. Sales $140,000, operating expenses $30,000. Find COGS, gross profit and profit.",exp:"COGS $89,000; GP $51,000; profit $21,000."},
{id:99,part:1,type:'mcq',q:"If closing WIP is larger than opening WIP, then compared with total manufacturing costs incurred, COGM will be:",opts:["lower","higher","the same","cannot be determined"],ans:0,exp:"COGM = opening WIP + costs incurred - closing WIP; a higher closing WIP reduces COGM."},
{id:100,part:1,type:'mcq',q:"A firm produces more than it sells, so closing finished goods exceeds opening finished goods. Compared with COGM, COGS will be:",opts:["higher","the same","lower","equal to purchases"],ans:2,exp:"COGS = opening FG + COGM - closing FG; an FG build-up means COGS < COGM."},
{id:101,part:2,type:'mcq',q:"The organisational value chain is best described as:",opts:["a list of the organisation's suppliers","the chain of command from the CEO to staff","a set of linked activities and processes that create value in a product or service","the sequence of journal entries in the ledger"],ans:2,exp:"Definition given in the lecture."},
{id:102,part:2,type:'mcq',q:"Which of the following is an UPSTREAM activity in the value chain?",opts:["Marketing","Research and development","Distribution","Customer service"],ans:1,exp:"Upstream: R&D, design, supply (before operations). Downstream: marketing, distribution, customer service."},
{id:103,part:2,type:'mcq',q:"Which of the following is a DOWNSTREAM activity in the value chain?",opts:["Research and development","Design","Supply","Distribution"],ans:3,exp:"Downstream = marketing, distribution and customer service."},
{id:104,part:2,type:'mcq',q:"Which of these is a SUPPORT service (not a primary activity)?",opts:["Operations","Marketing","Human resources","Supply"],ans:2,exp:"Support: HR, finance/accounting, general management, information systems."},
{id:105,part:2,type:'short',q:"List the primary activities in the value chain in order from upstream to downstream.",exp:"R&D -> Design -> Supply -> Operations -> Marketing -> Distribution -> Customer service (support: HR, finance/accounting, general management, information systems)."},
{id:106,part:2,type:'mcq',q:"For external reporting (absorption costing), which of these costs is a PERIOD cost rather than a product cost?",opts:["R&D and advertising","Direct materials","Direct labour","Factory rent"],ans:0,exp:"Product costs are manufacturing costs; R&D, advertising and corporate overhead are period costs."},
{id:107,part:2,type:'mcq',q:"A cost system estimates the cost of a cost object in two basic stages. They are:",opts:["cost allocation and cost elimination","cost accumulation and cost assignment","cost control and cost budgeting","cost pooling and cost auditing"],ans:1,exp:"The two basic stages of a costing system."},
{id:108,part:2,type:'mcq',q:"Cost accumulation is:",opts:["assigning costs to cost objects","adjusting under- or over-applied overhead","calculating the breakeven point","the process of collecting cost data in some organised way through an accounting system"],ans:3,exp:"Stage 1 (cost pools such as materials, labour, advertising)."},
{id:109,part:2,type:'mcq',q:"Cost assignment is:",opts:["the process of assigning accumulated costs to cost objects (tracing direct costs and allocating indirect costs)","collecting costs into cost pools","estimating the selling price","valuing closing inventory only"],ans:0,exp:"Stage 2."},
{id:110,part:2,type:'mcq',q:"Direct costs are assigned to cost objects by:",opts:["cost allocation","cost pooling","cost tracing","cost accumulation"],ans:2,exp:"Direct = traced; indirect = allocated."},
{id:111,part:2,type:'mcq',q:"Indirect costs are assigned to cost objects by:",opts:["cost tracing","direct measurement","cost elimination","cost allocation using an allocation base"],ans:3,exp:"Definition given in the lecture."},
{id:112,part:2,type:'short',q:"Distinguish between cost tracing and cost allocation, and between cost accumulation and cost assignment.",exp:"Tracing assigns direct costs based on the measured quantity of resources consumed; allocation assigns indirect costs using an allocation method/base. Accumulation collects costs into cost pools; assignment assigns those accumulated costs to cost objects (by tracing and allocating)."},
{id:113,part:2,type:'mcq',q:"Cost management is:",opts:["only the process of reducing all costs regardless of value","the set of actions managers take to increase the value of products and services and search for cost efficiencies","the preparation of external financial statements","the assignment of costs to jobs"],ans:1,exp:"Understanding the real causes (drivers/activities) of cost."},
{id:114,part:2,type:'tf',q:"Cost management focuses on understanding the drivers or activities that cause costs.",ans:true,exp:"As per the lecture."},
{id:115,part:2,type:'table',q:"(Quick Check 1) King Living manufactures lounge chairs with a separate assembly line for each type. Classify as direct or indirect for a lounge chair: Cost of fabric on a specific chair; Salary of factory manager; Electricity (single bill for whole factory); Hourly wages of assembly-line worker; Insurance for factory.",exp:"Fabric: Direct. Factory manager salary: Indirect. Electricity: Indirect. Assembly-line wages: Direct. Insurance: Indirect."},
{id:116,part:2,type:'table',q:"A bakery makes cakes (cost object = a cake). Classify direct/indirect: Flour used in a specific cake; Baker's wages on a specific custom cake (timesheet); Rent of the bakery; Oven depreciation; Bakery manager's salary.",exp:"Flour: Direct. Baker's wages on custom cake: Direct. Rent: Indirect. Oven depreciation: Indirect. Manager's salary: Indirect."},
{id:117,part:2,type:'mcq',q:"Variable cost (as a measure of product cost) includes:",opts:["DM, DL, VOH and FOH","DM, DL and variable overhead (VOH)","All costs in the value chain","Only DM"],ans:1,exp:"Excludes all fixed costs."},
{id:118,part:2,type:'mcq',q:"Absorption cost (full product cost, for external reporting) includes:",opts:["DM, DL and variable overhead only","All costs in the value chain including R&D and marketing","DM, DL, variable overhead and fixed overhead","Only DM and DL"],ans:2,exp:"Definition given in the lecture."},
{id:119,part:2,type:'mcq',q:"Full cost includes:",opts:["all costs in the value chain related to the product (upstream, downstream and corporate support costs)","only manufacturing costs","only variable costs","DM and DL only"],ans:0,exp:"Definition given in the lecture."},
{id:120,part:2,type:'calc',q:"A product has DM $12, DL $9, variable overhead $4, fixed overhead $7 per unit, plus upstream/downstream and corporate support costs of $10 per unit. Calculate its (a) variable cost, (b) absorption cost, (c) full cost.",exp:"(a) $25 (b) $32 (c) $42. 12+9+4=25; 25+7=32; 32+10=42."},
{id:121,part:2,type:'table',q:"A unit costs: DM $15, DL $11, VOH $6, FOH $9; R&D/design $3, marketing and distribution $5, corporate support $4 (all per unit). Complete: Variable cost (DM+DL+VOH); Absorption cost (adds FOH); Full cost (adds value-chain and corporate costs).",exp:"Variable cost=32. Absorption cost=41. Full cost=53. (32=15+11+6; 41=32+9; 53=41+3+5+4)"},
{id:122,part:2,type:'mcq',q:"Which costing system reports ONLY the actual costs of production (accurate but not timely)?",opts:["Actual costing","Normal costing","Standard costing","Budget costing"],ans:0,exp:"Actual costing."},
{id:123,part:2,type:'mcq',q:"Normal costing reports:",opts:["actual costs for all elements","predetermined rates for all elements","actual overhead only","actual DM and actual DL, but uses a predetermined rate to apply overhead"],ans:3,exp:"Timely but not necessarily accurate."},
{id:124,part:2,type:'mcq',q:"Standard costing uses predetermined rates for:",opts:["overhead only","direct labour only","direct materials only","all production costs (DM, DL and OH)"],ans:3,exp:"Definition given in the lecture."},
{id:125,part:2,type:'table',q:"Complete the table describing the three costing systems (DM, DL, Overhead for Actual costing / Normal costing / Standard costing).",exp:"Actual costing: Actual, Actual, Actual. Normal costing: Actual, Actual, Predetermined rate. Standard costing: Predetermined/standard, Predetermined/standard, Predetermined rate."},
{id:126,part:2,type:'mcq',q:"Which costing system is 'timely but not necessarily accurate' because overhead is applied using a predetermined rate?",opts:["Actual costing","Normal costing","Standard costing","Variable costing"],ans:1,exp:"Normal costing."},
{id:127,part:2,type:'tf',q:"Under normal costing, actual direct materials and direct labour are used but overhead is applied using a predetermined rate.",ans:true,exp:"Definition of normal costing."},
{id:128,part:2,type:'mcq',q:"The predetermined overhead rate is calculated as:",opts:["total actual overhead / total actual quantity of the allocation base","total budgeted overhead x budgeted quantity of allocation base","total budgeted overhead costs / total budgeted quantity of the allocation base","actual overhead / budgeted quantity of allocation base"],ans:2,exp:"Predetermined OH rate formula."},
{id:129,part:2,type:'mcq',q:"The predetermined overhead rate is calculated:",opts:["at the end of the accounting period","each time a job is completed","before the start of the accounting period","only when actual overhead is known"],ans:2,exp:"Step 1 of allocating indirect costs."},
{id:130,part:2,type:'mcq',q:"Applied overhead equals:",opts:["the predetermined rate x the actual quantity of the allocation base used","the actual overhead cost","the predetermined rate x the budgeted quantity of the allocation base","budgeted overhead / actual quantity of the base"],ans:0,exp:"Applied OH formula."},
{id:131,part:2,type:'mcq',q:"A cost-allocation base (cost driver) is:",opts:["a systematic way to link an indirect cost to cost objects, e.g. machine hours or direct labour cost","the total of all fixed costs","the selling price of the product","the number of accountants"],ans:0,exp:"Definition given in the lecture."},
{id:132,part:2,type:'mcq',q:"Which of these is a commonly used allocation base for manufacturing overhead?",opts:["Sales revenue of competitors","Machine hours","The CEO's salary","Share price"],ans:1,exp:"E.g. machine hours, DL hours, DL cost."},
{id:133,part:2,type:'calc',q:"Budgeted manufacturing overhead is $900,000 and budgeted machine hours are 30,000. Calculate the predetermined OH rate and the overhead applied to a job using 12 machine hours.",exp:"$30/MH; $360 applied. 900,000/30,000=30; 30x12=360."},
{id:134,part:2,type:'calc',q:"Budgeted overhead is $480,000 and budgeted direct labour hours (DLH) are 20,000. Calculate the rate, and the overhead applied to a job that uses 35 DLH.",exp:"$24/DLH; $840. 480,000/20,000=24; 24x35=840."},
{id:135,part:2,type:'calc',q:"Overhead is allocated on direct labour cost. Budgeted overhead is $600,000 and budgeted direct labour cost is $500,000. Find the OH rate and the OH applied to a job with $2,500 of direct labour cost.",exp:"120% of DL cost; $3,000. 600,000/500,000=1.20; 1.20x2,500=3,000."},
{id:136,part:2,type:'calc',q:"At the end of the year, actual machine hours were 26,000 and the predetermined rate was $34.50 per machine hour. How much overhead was applied?",exp:"$897,000. 34.50x26,000=897,000."},
{id:137,part:2,type:'calc',q:"Budgeted overhead $1,250,000; budgeted machine hours 25,000; budgeted DL hours 62,500. Compute the OH rate per machine hour and per DL hour.",exp:"$50/MH; $20/DLH."},
{id:138,part:2,type:'short',q:"Outline the three steps in allocating indirect costs in a conventional costing system.",exp:"1) Before the period, calculate the predetermined OH rate = budgeted OH / budgeted quantity of allocation base. 2) During the period, apply OH to jobs = rate x actual quantity of the base used. 3) At period end, compare applied OH with actual OH and adjust (write-off to COGS) for the under/over-applied amount."},
{id:139,part:2,type:'mcq',q:"Overhead is UNDER-applied when:",opts:["applied overhead is greater than actual overhead","budgeted overhead is greater than applied","actual overhead equals budgeted overhead","actual overhead is greater than applied overhead"],ans:3,exp:"Under-applied definition."},
{id:140,part:2,type:'mcq',q:"Overhead is OVER-applied when:",opts:["actual overhead is greater than applied overhead","applied overhead is greater than actual overhead","actual overhead is less than budgeted overhead","applied overhead equals actual overhead"],ans:1,exp:"Over-applied definition."},
{id:141,part:2,type:'mcq',q:"(Quick Check 2) Manufacturing overhead is overapplied when actual manufacturing overhead is:",opts:["greater than budgeted manufacturing overhead","less than budgeted manufacturing overhead","greater than applied manufacturing overhead","less than applied manufacturing overhead"],ans:3,exp:"Over-applied means applied > actual, i.e. actual < applied."},
{id:142,part:2,type:'mcq',q:"Under-applied overhead is written off to COGS by:",opts:["subtracting the difference from unadjusted COGS","adding it to revenue","adding the difference to unadjusted COGS","adding it to closing raw materials"],ans:2,exp:"Actual OH > applied OH, so COGS was too low."},
{id:143,part:2,type:'mcq',q:"Over-applied overhead is written off to COGS by:",opts:["adding the difference to unadjusted COGS","adding it to period expenses","ignoring it","subtracting the difference from unadjusted COGS"],ans:3,exp:"Applied OH > actual OH, so COGS was too high."},
{id:144,part:2,type:'mcq',q:"Compared with unadjusted profit, under-applied overhead leads to a ___ adjusted profit.",opts:["higher","unchanged","zero","lower"],ans:3,exp:"Adjusted COGS goes up, so profit goes down."},
{id:145,part:2,type:'tf',q:"Unadjusted COGS is the COGS figure that includes applied (not actual) overhead.",ans:true,exp:"Definition given in the lecture."},
{id:146,part:2,type:'calc',q:"Actual overhead $512,000; applied overhead $500,000; unadjusted COGS $2,000,000. Is OH under- or over-applied? Find adjusted COGS.",exp:"Under-applied by $12,000; adjusted COGS $2,012,000."},
{id:147,part:2,type:'calc',q:"Actual overhead $480,000; applied overhead $495,000; unadjusted COGS $1,800,000. Find the under/over-applied amount and adjusted COGS.",exp:"Over-applied by $15,000; adjusted COGS $1,785,000."},
{id:148,part:2,type:'calc',q:"A firm applies OH at $42 per machine hour. Actual machine hours were 8,000 and actual overhead was $330,000. Calculate applied overhead and state whether it is under or over-applied.",exp:"Applied $336,000; over-applied by $6,000."},
{id:149,part:2,type:'table',q:"Determine the under/(over)-applied overhead and adjusted COGS: Case 1 (Actual 250,000, Applied 260,000, Unadjusted COGS 1,500,000); Case 2 (Actual 310,000, Applied 300,000, Unadjusted COGS 1,200,000); Case 3 (Actual 420,000, Applied 420,000, Unadjusted COGS 900,000).",exp:"Case 1: over-applied (10,000); Adjusted COGS 1,490,000. Case 2: under-applied 10,000; Adjusted COGS 1,210,000. Case 3: 0; Adjusted COGS 900,000."},
{id:150,part:2,type:'calc',q:"(Lecture Q1) Actual manufacturing overhead $680,000; budgeted machine hours 15,000; budgeted DL hours 30,000; budgeted overhead $700,000; actual machine hours 18,000; actual DL hours 29,000. Calculate the predetermined OH rate using (a) machine hours and (b) DL hours, then the over/under-applied OH using each driver.",exp:"(a) $46.67/MH -> applied $840,000, OVER-applied $160,000. (b) $23.33/DLH -> applied $676,667, UNDER-applied $3,333."},
{id:151,part:2,type:'mcq',q:"(Lecture Q1, part 3) Using the Lecture Q1 data, which cost driver is more appropriate?",opts:["Machine hours - it always gives the larger applied overhead","Neither - a predetermined rate cannot be used with two drivers","Direct labour hours - it gives a much smaller under/over-application (about $3,333 vs $160,000), so applied overhead is closer to actual","Machine hours - because over-applied overhead is always better than under-applied"],ans:2,exp:"The driver with the smaller variance tracks actual overhead more closely."},
{id:152,part:2,type:'short',q:"Why can a predetermined overhead rate produce under- or over-applied overhead? Suggest why firms still use one.",exp:"Because the rate is set from budgeted overhead and budgeted activity before the period, while actual overhead and actual activity differ. Firms use it because actual overhead is not known until the end of the period, and a predetermined rate lets them cost jobs and set prices in a timely way (normal costing)."},
{id:153,part:2,type:'mcq',q:"In a normal costing system, job cost is made up of:",opts:["actual direct costs plus allocated (applied) indirect costs","actual direct and actual indirect costs only","standard direct costs only","variable costs only"],ans:0,exp:"Job cost components under normal costing."},
{id:154,part:2,type:'mcq',q:"Under the cost-plus method, the product price is:",opts:["product cost / (1 + markup %)","product cost x (1 + markup %)","product cost + markup % of selling price","product cost - markup"],ans:1,exp:"Cost-plus pricing formula."},
{id:155,part:2,type:'calc',q:"A job costs $200 to make. The firm's markup is 30% on cost. What is the price?",exp:"$260. 200x1.30=260."},
{id:156,part:2,type:'calc',q:"A product is priced at $312 using a 20% cost-plus markup. What is the product cost?",exp:"$260. Cost=312/1.20=260."},
{id:157,part:2,type:'calc',q:"Job 101 used direct materials $5,000 and 150 direct labour hours at $20 per hour. Overhead is applied at $15 per DL hour. Calculate the job cost and the price using a 40% cost-plus markup.",exp:"Job cost $10,250; price $14,350. DL=3,000; OH=2,250; cost=5,000+3,000+2,250=10,250; price=10,250x1.4=14,350."},
{id:158,part:2,type:'table',q:"Job cost sheet for Job A (cost-plus markup 25%): Direct materials (actual) 3,200; Direct labour (actual) 1,800; Overhead applied (120% of DL cost) ?; Total job cost ?; Markup (25%) ?; Price ?.",exp:"OH applied=2,160. Total job cost=7,160. Markup=1,790. Price=8,950."},
{id:159,part:2,type:'tf',q:"Overhead in a normal-costing job cost is an actual amount traced to the job.",ans:false,exp:"It is estimated using the predetermined rate and cost driver."},
{id:160,part:2,type:'mcq',q:"Job costing is appropriate when:",opts:["each product or batch is significantly different (heterogeneous)","many identical units flow through a continuous process","there is only one process department","no inventory is held"],ans:0,exp:"Cost object = job."},
{id:161,part:2,type:'mcq',q:"Process costing is appropriate when:",opts:["many units of a single homogeneous product flow evenly through a continuous production process","each product is unique","the firm produces custom-designed products","costs are traced to individual customers"],ans:0,exp:"Cost object = process/department."},
{id:162,part:2,type:'mcq',q:"In process costing, the cost object is:",opts:["the job","the customer","the batch order","the process or department"],ans:3,exp:"Costs are averaged across all units produced."},
{id:163,part:2,type:'mcq',q:"In job costing, the cost object is:",opts:["the process","the department","the job","the industry"],ans:2,exp:"Manufacturing costs are traced to individual jobs."},
{id:164,part:2,type:'table',q:"(Quick Check 3) Would each business use job costing or process costing? Law firms; Custom-designed home builders; Plastic manufacturers; Electricity providers; Food and beverage manufacturers.",exp:"Law firms: Job costing. Custom home builders: Job costing. Plastic manufacturers: Process costing. Electricity providers: Process costing. Food and beverage manufacturers: Process costing."},
{id:165,part:2,type:'mcq',q:"A car customising workshop is most likely to use:",opts:["process costing","no costing system","job costing","standard process costing only"],ans:2,exp:"Every car is customised differently (heterogeneous)."},
{id:166,part:2,type:'mcq',q:"A large-scale car factory (e.g. Tesla) producing identical models on a continuous line is most likely to use:",opts:["job costing","process costing","cost-plus only","neither"],ans:1,exp:"Homogeneous output on a continuous production line."},
{id:167,part:2,type:'mcq',q:"In the Job costing diagram, DM, DL and manufacturing overhead are first accumulated in:",opts:["Cost of goods sold","Separate WIP accounts for each job","A single WIP account per production department","Finished goods"],ans:1,exp:"Job costing accumulates costs by job order within WIP."},
{id:168,part:2,type:'mcq',q:"In the Process costing diagram, DM, DL and manufacturing overhead are accumulated in:",opts:["Separate WIP accounts for each production department","A separate WIP account for each customer order","Cost of goods sold","Raw materials"],ans:0,exp:"Costs go to Department A WIP, then Department B WIP, then Finished Goods, then COGS."},
{id:169,part:2,type:'tf',q:"Process costing averages the accumulated department costs across all units produced.",ans:true,exp:"As per the lecture."},
{id:170,part:2,type:'tf',q:"Job costing is the appropriate system for a firm producing identical bottles on a continuous line.",ans:false,exp:"That is process costing."},
{id:171,part:2,type:'short',q:"Compare job costing and process costing (cost object, product type and cost flow).",exp:"Job: cost object = job, heterogeneous/custom products, costs traced to jobs in WIP then FG then COGS. Process: cost object = process/department, homogeneous product on a continuous flow, costs accumulated by department and averaged over units, then FG then COGS."},
{id:172,part:2,type:'mcq',q:"(Quick Check 4) Costs added to the production process are accumulated in which account?",opts:["Raw materials inventory","Work in process inventory","Finished goods inventory","Cost of goods sold"],ans:1,exp:"DM, DL and applied OH accumulate in WIP."},
{id:173,part:2,type:'mcq',q:"In the general ledger, the credit side of the WIP account 'COGM' is transferred to:",opts:["Cost of goods sold","Finished goods inventory","Raw materials","Overhead"],ans:1,exp:"Completed production moves from WIP to FG."},
{id:174,part:2,type:'mcq',q:"Unadjusted COGS in the ledger is the amount transferred from:",opts:["Finished goods to the COGS expense account (P&L)","WIP to finished goods","Raw materials to WIP","Overhead to WIP"],ans:0,exp:"Standard cost-flow ledger transfer."},
{id:175,part:2,type:'mcq',q:"The debit side of the WIP account in a job-costing system includes:",opts:["actual overhead and selling costs","COGS","only applied overhead","direct materials, direct labour and applied overhead"],ans:3,exp:"Overhead is ALLOCATED to WIP, not the actual amount."},
{id:176,part:2,type:'mcq',q:"The closing balance of WIP represents:",opts:["unsold completed goods at period end","the goods completed this period","the COGS expense","incomplete production at the end of the period"],ans:3,exp:"Definition given in the lecture."},
{id:177,part:2,type:'mcq',q:"The closing balance of Finished Goods represents:",opts:["incomplete production","goods completed this period","unadjusted COGS","unsold completed goods at the end of the period"],ans:3,exp:"Definition given in the lecture."},
{id:178,part:2,type:'table',q:"Complete for the cost object 'product': Direct materials/direct labour (Direct/Indirect, Behaviour, Assignment method); Variable manufacturing overhead (Behaviour=Variable); Fixed manufacturing overhead (Direct/Indirect=Indirect).",exp:"DM/DL: Direct, Variable, Cost tracing. VOH: Indirect, Variable, Cost allocation (applied using OH driver). FOH: Indirect, Fixed, Cost allocation (applied using OH driver)."},
{id:179,part:2,type:'mcq',q:"Fixed manufacturing overhead is classified as:",opts:["a direct variable cost traced to the product","an indirect fixed cost, allocated using the overhead driver","a period cost","a direct fixed cost"],ans:1,exp:"Part of absorption cost and allocated."},
{id:180,part:2,type:'table',q:"(Lecture Q2) DM: beginning 100, purchases 150, ending 25, used ?; WIP: beginning 200, DL 50, OH applied 220, ending 55, COGM ?; FG: beginning 115, ending 90, COGS (unadjusted) ?; Revenue 900, COGS* (adjusted for 50 under-applied OH) ?, Gross profit ?, Period expenses 235, Profit (loss) ?.",exp:"DM used=225. COGM=640. COGS(unadjusted)=665. COGS*=715. GP=185. Profit=(50) a loss."},
{id:181,part:2,type:'table',q:"(Lecture Q3, part A) Benny Manufacturing: began Sept with RM $35,000, WIP $40,000, FG $25,000. Materials purchased $48,500; DM issued to production $62,000; OH applied at 80% of DL cost; indirect materials/supplies $6,000; DL payroll $40,000; indirect labour payroll $10,000; misc mfg expenses $12,600. Find: Actual MOH; Applied OH; Under/(over)-applied OH; Closing RM; Closing WIP.",exp:"Actual MOH=28,600. Applied=32,000. Over-applied by 3,400. Closing RM=15,500. Closing WIP=19,000."},
{id:182,part:2,type:'table',q:"(Lecture Q3, part B) Prepare Benny Manufacturing's schedule of COGS (with OH adjustment) and income statement: Opening FG 25,000; COGM 155,000; Closing FG 20,000; Sales revenue 225,000; Marketing & admin (full expense) 20,000.",exp:"Cost of goods available for sale=180,000. Unadjusted COGS=160,000. Adjusted COGS=156,600 (over-applied 3,400 reduces it). GP=68,400. Profit before tax=48,400."},
{id:183,part:2,type:'mcq',q:"In the Benny Manufacturing question, why is the full $20,000 of marketing and administration expense deducted even though only half was paid?",opts:["Because only half is a period cost","Under accrual accounting, expenses are recognised when incurred, not when paid","Because marketing and administration costs are inventoriable","Because half is added to COGS"],ans:1,exp:"Payment timing affects cash, not the expense."},
{id:184,part:2,type:'mcq',q:"Cost pools in the cost accumulation stage are typically:",opts:["allocation bases such as machine hours","the cost objects themselves","self-descriptive classifications of cost such as materials, labour and advertising","the predetermined overhead rates"],ans:2,exp:"Stage 1 of a costing system collects costs into cost pools."},
{id:185,part:2,type:'mcq',q:"Which cost measure is used for EXTERNAL reporting of product cost?",opts:["Variable cost","Full value-chain cost","Absorption (full manufacturing) cost","Marginal cost of the last unit"],ans:2,exp:"Absorption cost includes DM, DL, VOH and FOH; R&D, marketing etc. are period costs."},
{id:186,part:2,type:'tf',q:"A cost can be both direct and variable (for example, direct materials).",ans:true,exp:"Direct/indirect (traceability) and variable/fixed (behaviour) are separate dimensions."},
{id:187,part:2,type:'mcq',q:"Applying overhead with a single predetermined rate based on one allocation base is characteristic of:",opts:["conventional (traditional) product costing systems","activity-based costing systems with many cost pools","actual costing only","process costing only"],ans:0,exp:"Conventional systems use a single predetermined overhead rate."},
{id:188,part:2,type:'calc',q:"Jobs A and B are the only jobs in a period. Job A used 40 direct labour hours and Job B used 65. OH is applied at $18 per DLH. Actual overhead was $1,950. Find applied OH and the under/over-applied amount.",exp:"Applied $1,890; under-applied by $60."},
{id:189,part:2,type:'calc',q:"Unadjusted profit is $250,000 and overhead is under-applied by $30,000. What is the adjusted profit (write-off to COGS approach)?",exp:"$220,000. Under-applied OH increases COGS by 30,000, so profit falls."},
{id:190,part:2,type:'calc',q:"Work in process: opening $30,000; direct materials used $100,000; direct labour $60,000; overhead applied $90,000; closing $40,000. Find COGM.",exp:"$240,000. 30,000+100,000+60,000+90,000-40,000=240,000."},
{id:191,part:2,type:'calc',q:"Finished goods: opening $50,000; COGM $240,000; closing $60,000. Overhead was over-applied by $5,000. Find unadjusted and adjusted COGS.",exp:"Unadjusted $230,000; adjusted $225,000."},
{id:192,part:2,type:'table',q:"Ridge Cycles (all $000). Actual overhead 175, applied 160 (UNDER-applied). DM: beginning 60, purchases 200, ending 40, used ?; WIP: beginning 90, DL 130, OH applied 160, ending 70, COGM ?; FG: beginning 80, ending 110, COGS(unadjusted) ?, COGS(adjusted) ?; Revenue 780, GP ?, Period expenses 150, Profit ?.",exp:"DM used=220. COGM=530. COGS(unadjusted)=500. COGS(adjusted)=515 (under-applied 15 added). GP=265. Profit=115."},
{id:193,part:2,type:'table',q:"Summit Tools (all $000). Overhead OVER-applied by 12. DM: beginning 50, purchases 180, ending 30, used ?; WIP: beginning 60, DL 120, OH applied 150, ending 80, COGM ?; FG: beginning 70, ending 50, COGS(unadjusted) ?, COGS(adjusted) ?; Revenue 700, GP ?, Period expenses 140, Profit ?.",exp:"DM used=200. COGM=450. COGS(unadjusted)=470. COGS(adjusted)=458. GP=242. Profit=102."},
{id:194,part:2,type:'table',q:"Predetermined OH rates: budgeted OH $360,000; budgeted MH 12,000; budgeted DLH 18,000; actual MH 12,600; actual DLH 17,500; actual OH $375,000 (both). Find rate, applied OH, over/(under)-applied for each driver.",exp:"MH rate=$30, applied=378,000, over-applied 3,000. DLH rate=$20, applied=350,000, under-applied 25,000."},
{id:195,part:2,type:'mcq',q:"In process costing, costs move sequentially through:",opts:["Department A WIP, Department B WIP, Finished goods, COGS","Job 1 WIP, Job 2 WIP, Job 3 WIP, COGS","Finished goods, Department A WIP, COGS","Raw materials, COGS, Department A WIP"],ans:0,exp:"Costs accumulate by production department."},
{id:196,part:2,type:'short',q:"Compare actual costing, normal costing and standard costing.",exp:"Actual: actual DM, DL and OH (accurate, not timely). Normal: actual DM and DL but OH applied with a predetermined rate (timely, not necessarily accurate). Standard: predetermined (budgeted/standard) rates for all of DM, DL and OH."},
{id:197,part:2,type:'short',q:"Explain how under- or over-applied overhead is dealt with at period end (write-off to COGS approach) and what it does to profit.",exp:"Compare applied OH with actual OH. If actual > applied (under-applied) add the difference to unadjusted COGS, reducing profit. If applied > actual (over-applied) subtract the difference from unadjusted COGS, increasing profit."},
{id:198,part:2,type:'table',q:"Kestrel Furniture: DM used $90,000; DL $60,000; OH applied at 150% of DL cost; actual OH $95,000; WIP opening/closing $20,000/$25,000; FG opening/closing $30,000/$35,000; revenue $400,000; period expenses $70,000. Find OH applied, total mfg costs, COGM, unadjusted COGS, under-applied OH, adjusted COGS, gross profit, profit before tax.",exp:"OH applied=90,000. Total mfg costs=240,000. COGM=235,000. Unadjusted COGS=230,000. Under-applied OH=5,000. Adjusted COGS=235,000. GP=165,000. Profit=95,000."},
{id:199,part:2,type:'mcq',q:"For Kestrel Furniture, actual overhead ($95,000) exceeds applied overhead ($90,000). The effect on COGS and profit is:",opts:["COGS rises by $5,000 and profit falls by $5,000","COGS falls by $5,000 and profit rises by $5,000","COGS and profit are unchanged","COGS rises by $5,000 and profit rises by $5,000"],ans:0,exp:"Under-applied overhead is added to unadjusted COGS."},
{id:200,part:2,type:'calc',q:"Job B: direct materials $2,400; direct labour 65 hours at $22 per hour; overhead applied at $18 per DL hour; cost-plus markup 35%. Find the job cost and the price.",exp:"Job cost $5,000; price $6,750."},
{id:201,part:3,type:'mcq',q:"Cost behaviour is:",opts:["the way a cost is recorded in the ledger","how a cost is allocated to a department","whether a cost is direct or indirect","the relationship between a cost (total or per unit) and the level of activity or cost driver"],ans:3,exp:"Definition given in the lecture."},
{id:202,part:3,type:'mcq',q:"A cost driver is:",opts:["any fixed cost","the total of all costs","the selling price","a variable, such as the level of activity or volume, that causally affects costs over a given time span"],ans:3,exp:"Definition given in the lecture."},
{id:203,part:3,type:'mcq',q:"Variable costs (VC) are costs that:",opts:["stay the same in total whatever the volume","stay the same per unit and per total","change in total in proportion to changes in the related level of activity or volume","only change when selling prices change"],ans:2,exp:"Definition given in the lecture."},
{id:204,part:3,type:'mcq',q:"Fixed costs (FC) are costs that:",opts:["remain unchanged in total for a given time period despite wide changes in activity or volume","change in total in proportion to volume","are constant per unit at all volumes","are always uncontrollable"],ans:0,exp:"Definition given in the lecture."},
{id:205,part:3,type:'mcq',q:"As volume increases within the relevant range, which of these happens?",opts:["Variable cost per unit falls and fixed cost per unit is constant","Variable cost per unit is constant and fixed cost per unit falls","Both fall","Both rise"],ans:1,exp:"VC per unit is constant; FC per unit = FC/volume falls."},
{id:206,part:3,type:'mcq',q:"Variable and fixed cost behaviour patterns are valid only:",opts:["at any volume and over any time period","outside the relevant range","within a given relevant range and for a given time period","for one product only"],ans:2,exp:"Definition given in the lecture."},
{id:207,part:3,type:'mcq',q:"The relevant range is:",opts:["the range of activity (upper and lower limits of production) over which cost-behaviour assumptions hold","the range of selling prices","the range of profits","the difference between budgeted and actual"],ans:0,exp:"Definition given in the lecture."},
{id:208,part:3,type:'mcq',q:"Which of these may change if activity moves outside the relevant range?",opts:["Neither fixed costs nor variable cost per unit","Both fixed costs and variable cost per unit","Only the selling price","Only closing inventory"],ans:1,exp:"Beyond capacity you would need to expand (higher FC) and VC per unit could change."},
{id:209,part:3,type:'mcq',q:"A production level beyond the relevant range would typically require:",opts:["a reduction in fixed costs","capacity expansion (higher fixed costs) and could change variable cost per unit","no change in any cost","the removal of all variable costs"],ans:1,exp:"Definition given in the lecture."},
{id:210,part:3,type:'mcq',q:"A cost that is constant within a band of activity but jumps to a higher level when that band is exceeded (e.g. supervisors hired per 10,000 units) is:",opts:["variable cost","semi-variable (mixed) cost","curvilinear cost","stepped-fixed cost"],ans:3,exp:"Definition given in the lecture."},
{id:211,part:3,type:'mcq',q:"A cost with both fixed and variable components (e.g. an electricity bill with a fixed charge plus a usage charge) is:",opts:["semi-variable (mixed) cost","stepped-fixed cost","purely fixed cost","purely variable cost"],ans:0,exp:"Mixed costs can often be split into variable and fixed components."},
{id:212,part:3,type:'mcq',q:"Costs that do not change in a straight line with activity (e.g. volume discounts causing a curved total cost) are:",opts:["curvilinear costs","stepped-fixed costs","linear variable costs","fixed costs"],ans:0,exp:"In ACCT1102 we assume all costs are linear."},
{id:213,part:3,type:'mcq',q:"(Quick Check 1.1) Manufacturing volume 50,000 units: total cost $97,500 ($1.95/unit); 70,000 units: $136,500 ($1.95/unit). This cost is:",opts:["Variable cost","Fixed cost","Semi-variable cost","Stepped fixed cost"],ans:0,exp:"Cost per unit is constant so total cost changes in proportion to volume: variable."},
{id:214,part:3,type:'mcq',q:"(Quick Check 1.2) Manufacturing volume 50,000 units: total cost $150,000 ($3.00/unit); 80,000 units: $150,000 ($1.88/unit). This cost is:",opts:["Variable cost","Fixed cost","Semi-variable cost","Stepped fixed cost"],ans:1,exp:"Total cost is unchanged while unit cost falls: fixed."},
{id:215,part:3,type:'table',q:"Classify the behaviour of each cost (variable, fixed, semi-variable, stepped-fixed): Direct materials; Straight-line depreciation on factory equipment; Sales commissions of 5% of revenue; Electricity ($500 monthly + $0.10/kWh); One supervisor per 10,000 units; Annual factory rent.",exp:"DM: Variable. Depreciation: Fixed. Commissions: Variable. Electricity: Semi-variable. Supervisor per 10,000 units: Stepped-fixed. Factory rent: Fixed."},
{id:216,part:3,type:'table',q:"For variable and fixed costs, state whether total cost and cost per unit stay constant or change as volume rises within the relevant range.",exp:"Variable: Total cost increases, cost per unit constant. Fixed: Total cost constant, cost per unit decreases."},
{id:217,part:3,type:'calc',q:"At 1,000 units total cost is $10,000; at 2,000 units $10,000; at 3,000 units $10,000. What cost pattern is this, and what is the cost per unit at each volume?",exp:"Fixed cost; $10.00, $5.00, $3.33 per unit."},
{id:218,part:3,type:'calc',q:"Total cost is $4,000 at 0 units, $9,000 at 1,000 units and $14,000 at 2,000 units. Identify the cost behaviour and write the cost function.",exp:"Semi-variable (mixed); Y = 4,000 + 5X."},
{id:219,part:3,type:'mcq',q:"In the cost function Y = FC + VC x X, Y represents:",opts:["total revenue","profit","total cost","the cost per unit"],ans:2,exp:"X is the activity level (e.g. units produced)."},
{id:220,part:3,type:'mcq',q:"On a graph of the cost function, the total cost line intercepts the vertical axis at:",opts:["variable cost per unit","zero","total revenue","fixed cost (FC)"],ans:3,exp:"TC = FC + VC x X, so at X=0, TC=FC."},
{id:221,part:3,type:'mcq',q:"The slope of the total cost line is:",opts:["fixed cost","the selling price","variable cost per unit","the CM ratio"],ans:2,exp:"TC rises by VC per additional unit."},
{id:222,part:3,type:'calc',q:"A firm's cost function is Y = 25,000 + 6X. What is total cost at 8,000 units, and cost per unit?",exp:"$73,000; $9.125 per unit."},
{id:223,part:3,type:'mcq',q:"(Quick Check 2) At a volume of 200,000 units, Lighthouse Corporation's total fixed costs were $800,000 and cost per unit totalled $11. What total cost would be expected at 202,000 units?",opts:["$1,608,000","$2,200,000","$2,214,000","$2,222,000"],ans:2,exp:"VC=$7/unit; 800,000+7x202,000=2,214,000."},
{id:224,part:3,type:'calc',q:"At 40,000 units, total fixed costs are $120,000 and total cost per unit is $9. What is the variable cost per unit and total cost at 45,000 units?",exp:"VC $6 per unit; total cost $390,000."},
{id:225,part:3,type:'calc',q:"A firm has fixed costs of $50,000 per month and variable costs of $12 per unit. Compute the total cost and cost per unit at 5,000 and at 10,000 units.",exp:"5,000: $110,000 ($22.00/unit); 10,000: $170,000 ($17.00/unit)."},
{id:226,part:3,type:'calc',q:"Electricity costs $500 per month plus $0.10 per kWh. Find the bill for 12,000 kWh and the total cost function.",exp:"$1,700; Y = 500 + 0.10X."},
{id:227,part:3,type:'mcq',q:"CVP analysis examines:",opts:["only the cost of goods sold","the relationships among revenues, costs, volume and profits","only external financial reports","only tax effects"],ans:1,exp:"Definition given in the lecture."},
{id:228,part:3,type:'mcq',q:"CVP analysis separates costs into:",opts:["direct and indirect only","product and period only","fixed and variable components and finds the activity level where costs equal revenues","controllable and uncontrollable only"],ans:2,exp:"Definition given in the lecture."},
{id:229,part:3,type:'short',q:"List decisions in which CVP analysis can guide managers.",exp:"Selling prices; target production and sales volumes; variable and fixed costs; fixed asset acquisitions; resource utilisation and disposal; product mix; product pricing."},
{id:230,part:3,type:'mcq',q:"Which of the following is NOT an assumption of basic CVP analysis?",opts:["Selling prices and variable cost per unit change in every period","Costs can be separated into fixed and variable categories","The revenue line is linear (uniform selling price)","All production is sold, or there is no significant change in inventory"],ans:0,exp:"CVP assumes constant selling price and constant CM per unit."},
{id:231,part:3,type:'mcq',q:"For multi-product firms CVP assumes:",opts:["the sales mix remains the same over the period","the sales mix changes every month","only one product exists","no variable costs exist"],ans:0,exp:"CVP assumption for multi-product firms."},
{id:232,part:3,type:'tf',q:"CVP assumes production technology, market conditions and management policies do not change over the period.",ans:true,exp:"CVP assumption."},
{id:233,part:3,type:'tf',q:"CVP analysis assumes that all production is sold, or that inventory levels do not change significantly.",ans:true,exp:"CVP assumption."},
{id:234,part:3,type:'mcq',q:"A firm expects to give volume discounts on high sales volumes, so the price per unit falls with volume. Which CVP assumption is violated?",opts:["Costs can be split into fixed and variable","There is one relevant range","All costs are indirect","A uniform selling price / linear revenue line"],ans:3,exp:"Discounts make revenue non-linear."},
{id:235,part:3,type:'mcq',q:"The basic profit equation is:",opts:["Profit = Total revenue + Total cost","Profit = Total cost - Total revenue","Profit = Fixed costs - Variable costs","Profit = Total revenue - Total cost"],ans:3,exp:"Basic profit equation."},
{id:236,part:3,type:'mcq',q:"Expanded, the profit equation is:",opts:["Profit = SP(Q) + FC + VC(Q)","Profit = SP - FC(Q) - VC","Profit = SP(Q) - FC - VC(Q)","Profit = VC(Q) - FC - SP(Q)"],ans:2,exp:"SP=unit price, Q=units, FC=total fixed cost, VC=variable cost per unit."},
{id:237,part:3,type:'mcq',q:"Contribution margin (CM) is:",opts:["sales revenue less variable costs - the amount that contributes to covering fixed costs and earning profit","sales revenue less all costs","sales revenue less fixed costs","sales revenue less cost of goods sold"],ans:0,exp:"CM = SP(Q) - VC(Q)."},
{id:238,part:3,type:'mcq',q:"Contribution margin per unit equals:",opts:["selling price per unit - fixed cost per unit","selling price per unit - variable cost per unit","selling price per unit + variable cost per unit","total revenue - total cost"],ans:1,exp:"Definition given in the lecture."},
{id:239,part:3,type:'mcq',q:"The CM ratio equals:",opts:["fixed costs / sales revenue","variable costs / CM","profit / sales revenue","CM per unit / selling price (or total CM / sales revenue)"],ans:3,exp:"Definition given in the lecture."},
{id:240,part:3,type:'tf',q:"Under the CVP assumptions the CM ratio is the same at all sales volumes.",ans:true,exp:"It is invariant to volume because SP and VC per unit are constant."},
{id:241,part:3,type:'calc',q:"SP = $80, VC = $52 per unit. Compute CM per unit and the CM ratio.",exp:"$28; 35%. 80-52=28; 28/80=0.35."},
{id:242,part:3,type:'calc',q:"Sales revenue is $500,000 and total variable costs are $320,000. Compute total CM and the CM ratio.",exp:"$180,000; 36%."},
{id:243,part:3,type:'calc',q:"A product sells for $25 with a CM ratio of 40%. What are variable cost per unit and CM per unit?",exp:"VC $15; CM $10."},
{id:244,part:3,type:'calc',q:"Each unit of a product earns a CM of $6 and fixed costs total $18,000. What is profit if 4,500 units are sold?",exp:"$9,000. CM=6x4,500=27,000; profit=27,000-18,000=9,000."},
{id:245,part:3,type:'calc',q:"A firm sells 12,000 units at $30 with VC $18 and FC $100,000. Find profit before tax.",exp:"$44,000. CM=12x12,000=144,000; profit=144,000-100,000=44,000."},
{id:246,part:3,type:'table',q:"(Lecture Q1a) Calculate CM and profit: SP $5.00, VC $2.00, FC $30,000, units sold 5,000.",exp:"Sales revenue 25,000; Variable costs 10,000; Contribution margin 15,000; Fixed costs 30,000; Profit/(Loss) (15,000)."},
{id:247,part:3,type:'calc',q:"(Lecture Q1b) Using SP $5, VC $2, FC $30,000, 5,000 units, calculate the CM ratio.",exp:"60%. CM/unit=3; 3/5=0.60."},
{id:248,part:3,type:'mcq',q:"Which of the following is TRUE about contribution margin and gross profit?",opts:["CM always equals gross profit","Gross profit deducts only variable costs","CM is calculated after deducting fixed manufacturing costs","CM separates costs by behaviour (variable/fixed) while gross profit separates them by function (manufacturing vs non-manufacturing)"],ans:3,exp:"CM and gross profit are generally different amounts."},
{id:249,part:3,type:'mcq',q:"Taxable profit is also called:",opts:["contribution margin","gross profit","pre-tax profit / profit before tax / operating income","net profit after tax"],ans:2,exp:"Definition given in the lecture."},
{id:250,part:3,type:'mcq',q:"The breakeven point is the level of sales or activity at which:",opts:["profit is zero (total revenue = total cost)","contribution margin is zero","fixed costs are zero","variable costs equal fixed costs"],ans:0,exp:"Definition given in the lecture."},
{id:251,part:3,type:'mcq',q:"Breakeven point in units equals:",opts:["fixed costs / CM ratio","variable costs / unit CM","fixed costs / unit CM","fixed costs x unit CM"],ans:2,exp:"Breakeven formula (units)."},
{id:252,part:3,type:'mcq',q:"Breakeven point in sales revenue equals:",opts:["fixed costs / unit CM","fixed costs / CM ratio","fixed costs x CM ratio","variable costs / CM ratio"],ans:1,exp:"Breakeven formula (revenue)."},
{id:253,part:3,type:'calc',q:"(Lecture Q1c) SP $5, VC $2, FC $30,000. Calculate breakeven in units and in revenue.",exp:"10,000 units; $50,000."},
{id:254,part:3,type:'calc',q:"FC $90,000; SP $60; VC $42. Calculate the breakeven point in units and in sales revenue.",exp:"5,000 units; $300,000."},
{id:255,part:3,type:'calc',q:"A firm has FC $240,000 and a CM ratio of 40%. What sales revenue is needed to break even?",exp:"$600,000."},
{id:256,part:3,type:'calc',q:"FC $48,000; unit CM $7.50. Breakeven units?",exp:"6,400 units."},
{id:257,part:3,type:'calc',q:"FC $100,000; SP $45; VC $28. Breakeven in units (round up)?",exp:"5,883 units. CM=17; 100,000/17=5,882.35 -> 5,883."},
{id:258,part:3,type:'mcq',q:"On a CVP graph, the breakeven point is:",opts:["where the fixed cost line meets the vertical axis","the intersection of the total revenue line and the total cost line","where the variable cost line is zero","the point of maximum profit"],ans:1,exp:"TR = TC (profit = 0)."},
{id:259,part:3,type:'mcq',q:"On a CVP graph, the area between the total revenue and total cost lines to the RIGHT of breakeven is the:",opts:["loss area","fixed cost area","relevant range","profit area"],ans:3,exp:"Left of breakeven is the loss area."},
{id:260,part:3,type:'mcq',q:"On a CVP graph, the fixed cost line is:",opts:["upward sloping from the origin","horizontal","downward sloping","vertical"],ans:1,exp:"Total fixed cost is constant."},
{id:261,part:3,type:'mcq',q:"On the CVP graph for SP $5, VC $2, FC $30,000, total revenue at the 10,000-unit breakeven point is:",opts:["$30,000","$20,000","$50,000","$100,000"],ans:2,exp:"10,000 x $5 = $50,000."},
{id:262,part:3,type:'table',q:"Complete the breakeven analysis: Product X (SP 40, VC 24, FC 80,000); Product Y (SP 25, VC 10, FC 120,000); Product Z (SP 100, VC 60, FC 200,000). Find unit CM, CM ratio, breakeven units, breakeven revenue.",exp:"X: CM=16, ratio 40%, BE units 5,000, BE revenue 200,000. Y: CM=15, ratio 60%, BE units 8,000, BE revenue 200,000. Z: CM=40, ratio 40%, BE units 5,000, BE revenue 500,000."},
{id:263,part:3,type:'short',q:"Explain why the breakeven point falls when the selling price rises (holding costs constant).",exp:"A higher price raises the unit CM (and CM ratio), so fewer units are needed to cover the same fixed costs: breakeven units = FC / unit CM."},
{id:264,part:3,type:'calc',q:"SP $5, VC $2, FC $30,000. How many units must be sold to earn a profit before tax of $9,000?",exp:"13,000 units."},
{id:265,part:3,type:'calc',q:"SP $60, VC $42, FC $90,000. Sales revenue required to earn a pre-tax profit of $36,000?",exp:"$420,000."},
{id:266,part:3,type:'calc',q:"SP $35, VC $18, FC $800,000. Units required for a pre-tax profit of $90,000 (round up)?",exp:"52,353 units."},
{id:267,part:3,type:'mcq',q:"Units required for a target profit before tax equal:",opts:["(fixed costs + target profit) / unit CM","(fixed costs - target profit) / unit CM","fixed costs / (unit CM + target profit)","target profit / unit CM"],ans:0,exp:"SP(Q) = FC + VC(Q) + Profit."},
{id:268,part:3,type:'calc',q:"A firm currently sells 15,000 units at CM $8 with FC $100,000. How many more units must it sell to double its current profit?",exp:"Current profit is $20,000; extra 2,500 units."},
{id:269,part:3,type:'calc',q:"With FC $75,000 and CM ratio 25%, what sales revenue produces a profit of $25,000?",exp:"$400,000."},
{id:270,part:3,type:'mcq',q:"Why must net profit after tax (NPAT) be converted to profit before tax (PBT) in CVP analysis?",opts:["Because a linear relationship does not exist between sales and NPAT","Because tax is a variable cost","Because tax is a fixed cost","Because NPAT is always negative"],ans:0,exp:"Definition given in the lecture."},
{id:271,part:3,type:'mcq',q:"PBT equals:",opts:["NPAT x (1 - tax rate)","NPAT / tax rate","NPAT x tax rate","NPAT / (1 - tax rate)"],ans:3,exp:"PBT formula."},
{id:272,part:3,type:'mcq',q:"The CVP formula including tax is:",opts:["SP(Q) = FC + VC(Q) + NPAT x (1 - t)","SP(Q) = FC + VC(Q) + [NPAT / (1 - t)]","SP(Q) = FC + VC(Q) + NPAT x t","SP(Q) = FC - VC(Q) + NPAT"],ans:1,exp:"CVP with tax formula."},
{id:273,part:3,type:'calc',q:"(Lecture Q1d) SP $5, VC $2, FC $30,000, tax rate 40%. How many units must be sold to earn NPAT of $4,000?",exp:"12,223 units (rounded up from 12,222.2)."},
{id:274,part:3,type:'calc',q:"NPAT target is $63,000 and the tax rate is 30%. What PBT is required?",exp:"$90,000."},
{id:275,part:3,type:'calc',q:"A firm has PBT of $120,000 and tax rate of 25%. What is NPAT?",exp:"$90,000."},
{id:276,part:3,type:'calc',q:"SP $35, VC $18, FC $800,000, tax 30%. Units required for an after-tax profit of $63,000?",exp:"52,353 units."},
{id:277,part:3,type:'calc',q:"SP $20, VC $12, FC $40,000, tax rate 35%. How many units to earn NPAT of $26,000?",exp:"10,000 units."},
{id:278,part:3,type:'tf',q:"The breakeven point is affected by the tax rate.",ans:false,exp:"At breakeven PBT=0 so tax=0; tax only affects the volume needed to earn a given AFTER-tax profit."},
{id:279,part:3,type:'table',q:"Complete the after-tax CVP analysis (SP $50, VC $30, FC $200,000, tax 30%): Unit CM; Target NPAT ($42,000); Required PBT; Units required; Tax at that volume.",exp:"Unit CM=20. Required PBT=60,000. Units required=13,000. Tax at that volume=18,000."},
{id:280,part:3,type:'table',q:"(Lecture Q2) Compute the missing amounts: Row 1 (Sales 110,000, VC 22,000, CM ?, FC ?, PBT 38,000, BE revenue ?); Row 2 (Sales 200,000, VC 120,000, CM ?, FC 50,000, PBT ?, BE revenue ?); Row 3 (Sales 300,000, VC ?, CM 195,000, FC 130,000, PBT ?, BE revenue ?).",exp:"Row1: CM=88,000; FC=50,000; BE=62,500. Row2: CM=80,000; PBT=30,000; BE=125,000. Row3: VC=105,000; PBT=65,000; BE=200,000."},
{id:281,part:3,type:'table',q:"(Lecture Q3 i) The Rich Coffee Company: sales (80,000 units) $3,600,000; cost of sales $2,500,000; gross profit $1,100,000; operating expenses $620,000; PBT $480,000; tax (30%) $144,000; NPAT $336,000. Variable costs $25/unit; fixed operating expenses $220,000 p.a. Restate the income statement in CM format.",exp:"Variable costs (80,000x$25)=2,000,000. Contribution margin=1,600,000. Fixed costs=1,120,000. (PBT/tax/NPAT unchanged.)"},
{id:282,part:3,type:'calc',q:"(Lecture Q3 ii) Using Rich Coffee's data (SP $45, VC $25, total FC $1,120,000), calculate the breakeven volume in units for last period.",exp:"56,000 units."},
{id:283,part:3,type:'calc',q:"(Lecture Q3 iii) Rich Coffee wants a pre-tax profit of $600,000. What sales volume is needed? Is it within the relevant range (capacity 120,000 units)?",exp:"86,000 units; yes - within capacity."},
{id:284,part:3,type:'calc',q:"(Lecture Q3 iv) Rich Coffee wants an after-tax profit of $420,000 (tax 30%). What sales volume is required?",exp:"86,000 units."},
{id:285,part:3,type:'calc',q:"Rich Coffee: how much extra profit before tax would an additional 5,000 units earn (still within capacity)?",exp:"$100,000. 5,000 x CM $20 = 100,000 (fixed costs unchanged)."},
{id:286,part:3,type:'mcq',q:"Rich Coffee has capacity of 120,000 units. A CVP analysis for 150,000 units would be unreliable because:",opts:["CVP cannot be used for more than 100,000 units","sales price would rise","150,000 is outside the relevant range, so fixed costs and unit variable costs may differ","tax rates change at that level"],ans:2,exp:"Beyond capacity expansion is needed."},
{id:287,part:3,type:'mcq',q:"For Rich Coffee, contribution margin ($1,600,000) differs from gross profit ($1,100,000) because:",opts:["GP deducts only variable costs while CM deducts only fixed costs","CM is calculated after tax while GP is before tax","the two must always be equal","they classify costs differently: GP deducts all manufacturing costs (including fixed), CM deducts all variable costs (including variable selling/admin)"],ans:3,exp:"Net difference $500,000."},
{id:288,part:3,type:'table',q:"(Lecture Q5) SP $35, VC $18/unit, FC $800,000, tax 30%. Required: units to earn operating income of $90,000, then the CM statement at that volume (rounded up to a whole unit).",exp:"Units required=52,353. Revenue=1,832,355. Variable costs=942,354. CM=890,001. PBT~90,001. Tax(30%)~27,000. NPAT~63,001."},
{id:289,part:3,type:'mcq',q:"Other things being equal, an increase in fixed costs will ___ the breakeven point.",opts:["lower","not change","raise","reduce the CM ratio only"],ans:2,exp:"BE = FC / CM."},
{id:290,part:3,type:'mcq',q:"Other things being equal, an increase in the selling price will ___ the breakeven point in units.",opts:["raise","lower","not change","make it zero"],ans:1,exp:"Unit CM rises."},
{id:291,part:3,type:'calc',q:"SP $5, VC $2, FC $30,000. If price rises to $5.50, what is the new breakeven in units (round up)?",exp:"8,572 units."},
{id:292,part:3,type:'calc',q:"SP $5, VC $2, FC $30,000. If fixed costs rise by $6,000, what is the new breakeven in units?",exp:"12,000 units."},
{id:293,part:3,type:'calc',q:"SP $5, VC $2, FC $30,000. If VC rises to $2.50, what is the new breakeven in units?",exp:"12,000 units."},
{id:294,part:3,type:'calc',q:"SP $5, VC $2, FC $30,000. Profit at 12,000 units?",exp:"$6,000."},
{id:295,part:3,type:'table',q:"(Lecture Q4 i) A firm considers replacing labour with machinery costing $800,000, depreciated straight-line over 10 years; direct labour would fall 50%. Price $70; DM $5; DL $20; factory overhead $86,000+$4/unit; selling & admin $54,000+$6/unit. Volume 9,000 units. Complete the CM statement for current and proposed (Sales revenue 630,000 each).",exp:"Current: VC=315,000, CM=315,000, FC=140,000, Profit=175,000. Proposed: VC=225,000, CM=405,000, FC=220,000, Profit=185,000."},
{id:296,part:3,type:'calc',q:"Lecture Q4 follow-up: At what volume are the current and proposed (automated) cost structures equally profitable? Which is better above that volume?",exp:"8,000 units; the automated (proposed) structure is better above it."},
{id:297,part:3,type:'calc',q:"Lecture Q4 follow-up: If volume falls to 7,000 units, which option gives the higher profit?",exp:"Current: $105,000 vs proposed $95,000. Current is better."},
{id:298,part:3,type:'calc',q:"Lecture Q4 follow-up: Compute the breakeven volume in units for the current and proposed options.",exp:"Current 4,000 units; proposed 4,889 units."},
{id:299,part:3,type:'mcq',q:"Automating replaces variable labour with fixed depreciation. Its effect on CM per unit and breakeven point is:",opts:["lower CM per unit and lower breakeven","no change to either","lower fixed cost and higher CM per unit","higher CM per unit but a higher fixed cost, so a higher breakeven"],ans:3,exp:"Proposed CM/unit $45 (vs $35) but FC $220,000 (vs $140,000): BE 4,889 vs 4,000."},
{id:300,part:3,type:'short',q:"Under what circumstances does a cost structure with higher fixed and lower variable costs (as in the automation decision) increase profit? Explain the risk.",exp:"When expected volume is high enough (above the indifference point) because each unit earns a higher CM. The risk is that if volume falls, the higher fixed costs mean lower profit or losses (higher breakeven)."},
{id:301,part:4,type:'mcq',q:"A budget is best defined as:",opts:["a record of historical transactions","the quantitative expression of a proposed plan of action by management for a specified period","a legal report to shareholders","a list of past variances"],ans:1,exp:"Definition given in the lecture."},
{id:302,part:4,type:'mcq',q:"A budget is also:",opts:["a substitute for strategy","an audit report","an aid to coordinate what needs to be done to implement the plan","a tax return"],ans:2,exp:"Definition given in the lecture."},
{id:303,part:4,type:'mcq',q:"Budgets generally include:",opts:["both financial and non-financial aspects of the plan","only financial aspects","only non-financial aspects","only historical data"],ans:0,exp:"A 'road map' for the upcoming period."},
{id:304,part:4,type:'mcq',q:"Budgets help managers to:",opts:["eliminate all uncertainty","avoid all planning","replace financial accounting","communicate directions and goals, judge performance against plans, and motivate employees"],ans:3,exp:"Three main benefits of budgets."},
{id:305,part:4,type:'mcq',q:"(Quick Check 1, adapted) Budgets:",opts:["provide a measure of actual historical results only","are prepared independent of the company's long-term strategies","do not usually reflect actual results, so they are a useless exercise","serve as the financial expression of management's plans for the upcoming period"],ans:3,exp:"Budgets should be linked to strategy, not independent of it, and are not useless."},
{id:306,part:4,type:'mcq',q:"(Quick Check 2) Which of the following is NOT a major benefit of budgets?",opts:["Compels planning","Eliminates innovation","Provides performance criteria","Promotes coordination and communication"],ans:1,exp:"Budgets do not eliminate innovation."},
{id:307,part:4,type:'mcq',q:"Well-administered budgets offer which THREE main benefits?",opts:["Guarantee profit; eliminate variances; reduce all costs to zero","Replace strategy; remove uncertainty; avoid audits","Promote coordination and communication; provide a framework for judging performance and learning; motivate managers and employees","Increase inventory; reduce sales; remove departments"],ans:2,exp:"The three benefits given in the lecture."},
{id:308,part:4,type:'mcq',q:"Comparing budgets with actual results provides:",opts:["a guarantee that the plan is correct","a tax deduction","a legal report for ASIC","a framework for judging performance and facilitating learning"],ans:3,exp:"Definition given in the lecture."},
{id:309,part:4,type:'short',q:"Explain three ways budgets help managers.",exp:"(1) Communicate directions and goals to different departments so they can coordinate; (2) judge performance by measuring financial results against planned objectives, activities and timelines to identify problems; (3) motivate employees to achieve their goals."},
{id:310,part:4,type:'mcq',q:"A key challenge in administering budgets is that the budgeting process is:",opts:["time-consuming (senior managers spend about 10-20% of their time, finance planning departments up to 50%)","too fast to be useful","free of cost","only needed by external auditors"],ans:0,exp:"The annual budget process is a months-long exercise using many resources."},
{id:311,part:4,type:'tf',q:"Challenging budget targets can motivate managers and employees to greater effort.",ans:true,exp:"As per the lecture."},
{id:312,part:4,type:'mcq',q:"Budgeting is most useful when it is:",opts:["prepared independently of strategy","integrated with the company's strategy","prepared by external auditors","based only on last year's results"],ans:1,exp:"Definition given in the lecture."},
{id:313,part:4,type:'mcq',q:"Strategy specifies how an organisation:",opts:["matches its capabilities with the opportunities in the marketplace to accomplish its objectives","minimises its tax","records historical data","eliminates competition"],ans:0,exp:"Definition given in the lecture."},
{id:314,part:4,type:'mcq',q:"A strategy of providing quality products or services at a low price is:",opts:["product differentiation","cost leadership","rolling budgeting","kaizen budgeting"],ans:1,exp:"Definition given in the lecture."},
{id:315,part:4,type:'mcq',q:"A strategy of providing a unique product or service priced higher than competitors' is:",opts:["cost leadership","stretch targeting","product differentiation","budgetary slack"],ans:2,exp:"Definition given in the lecture."},
{id:316,part:4,type:'table',q:"Classify the generic strategy: Sells basic groceries at consistently low prices; Sells premium, uniquely designed products at higher prices; Builds a low-cost operation to offer quality at a low price; Competes on unique features and brand.",exp:"Groceries at low prices: Cost leadership. Premium unique products: Product differentiation. Low-cost operation: Cost leadership. Unique features/brand: Product differentiation."},
{id:317,part:4,type:'short',q:"List four questions managers consider when developing a successful strategy.",exp:"Any four of: What are our objectives? How do we create value for customers while distinguishing ourselves from competitors? Are the markets local, regional, national or global? What trends affect our markets? How do the economy, industry and competitors affect us? What organisational and financial structures serve us best? What are the risks/opportunities of alternative strategies and our contingency plans?"},
{id:318,part:4,type:'mcq',q:"The three steps in the ongoing budget-related process (budgeting cycle) begin with:",opts:["auditors verifying the actual results","shareholders voting on the plan","managers at all levels using past performance, market feedback and expected changes to initiate plans before the fiscal year starts","reporting the variances to ASIC"],ans:2,exp:"Step 1 of the budgeting cycle."},
{id:319,part:4,type:'short',q:"Describe the three steps of the budgeting cycle.",exp:"1) Before the fiscal year, managers at all levels consider past performance, market feedback and expected changes to initiate plans. 2) At the beginning of the year, senior managers give subordinate managers a frame of reference - specific expectations against which actual results are compared. 3) During the year, managers and management accountants investigate deviations from the plan. The working document at the core is the master budget."},
{id:320,part:4,type:'mcq',q:"The master budget expresses management's:",opts:["historical results only","tax plans only","operating and financial plans for a specified period","cash forecasts only"],ans:2,exp:"Definition given in the lecture."},
{id:321,part:4,type:'mcq',q:"Operating decisions deal with:",opts:["how to obtain the funds to acquire resources","how to report to ASIC","how to audit inventory","how to best use the limited resources of an organisation (the operating budget)"],ans:3,exp:"Definition given in the lecture."},
{id:322,part:4,type:'mcq',q:"Financial decisions deal with:",opts:["how to best use limited resources","how to obtain the funds to acquire resources (the financial budget)","how to price products","how to allocate overheads"],ans:1,exp:"Definition given in the lecture."},
{id:323,part:4,type:'table',q:"Classify each budget as part of the OPERATING budget or the FINANCIAL budget: Revenues budget; Cost of goods sold budget; Budgeted income statement; Cash budget; Budgeted balance sheet; Production budget; Direct materials budget.",exp:"Operating: Revenues budget, COGS budget, Budgeted income statement, Production budget, Direct materials budget. Financial: Cash budget, Budgeted balance sheet."},
{id:324,part:4,type:'mcq',q:"(Quick Check 3) The master budget consists of operating budgets and financial budgets. The operating budgets include:",opts:["sales budgets and various cost budgets","sales budgets and budgeted cash flow","income budget and budgeted cash flow","cash budget and various cost budget"],ans:0,exp:"Cash flow/cash budget is a FINANCIAL budget."},
{id:325,part:4,type:'short',q:"List the components of the operating budget and of the financial budget (noting which are not part of ACCT1102).",exp:"Operating: revenues budget, various cost budgets, COGS budget (manufacturers only), budgeted income statement. Financial: capital expenditure budget (not ACCT1102), cash budget, budgeted balance sheet, budgeted statement of cash flows (not ACCT1102)."},
{id:326,part:4,type:'mcq',q:"Which financial-budget components are NOT part of ACCT1102?",opts:["Capital expenditures budget and budgeted statement of cash flows","Cash budget and budgeted balance sheet","Revenues budget and production budget","Budgeted income statement and COGS budget"],ans:0,exp:"Those two are excluded from ACCT1102's scope."},
{id:327,part:4,type:'mcq',q:"Which budget is the starting point of the basic operating budget for a manufacturer?",opts:["The revenues (sales) budget","The production budget","The cost of goods sold budget","The budgeted income statement"],ans:0,exp:"Schedule 1."},
{id:328,part:4,type:'mcq',q:"Which budget is prepared immediately AFTER the revenues budget in a manufacturer's operating budget?",opts:["The direct labour budget","The production budget","The COGS budget","The cash budget"],ans:1,exp:"Schedule 1 then Schedule 2."},
{id:329,part:4,type:'table',q:"Match the schedule number to the budget: Schedule 1; Schedule 2; Schedules 3A & 3B; Schedule 4; Schedule 5; Schedules 6A & 6B; Schedule 7; Schedule 8; Exhibit 6-3.",exp:"1: Revenues budget. 2: Production budget. 3A&3B: DM usage & purchases budget. 4: Direct manufacturing labour costs budget. 5: Manufacturing overhead costs budget. 6A&6B: Ending inventories budget. 7: Cost of goods sold budget. 8: Nonmanufacturing costs budget. Exhibit 6-3: Budgeted income statement."},
{id:330,part:4,type:'short',q:"List, in order, the nine basic steps in preparing a manufacturer's operating budget.",exp:"1) Revenues budget; 2) production budget; 3) direct materials usage & purchases budget; 4) direct manufacturing labour costs budget; 5) manufacturing overhead costs budget; 6) ending inventories budget; 7) cost of goods sold budget; 8) nonmanufacturing costs budget; 9) budgeted income statement."},
{id:331,part:4,type:'short',q:"List the steps in preparing the financial budget (after the operating budget).",exp:"1) Capital expenditures budget (not ACCT1102); 2) cash budget; 3) budgeted balance sheet; 4) budgeted statement of cash flows (not ACCT1102)."},
{id:332,part:4,type:'mcq',q:"In the master-budget diagram, the production budget takes inputs from the revenues budget and from the:",opts:["capital expenditures budget","cash budget","budgeted balance sheet","ending inventory budget (desired closing inventories)"],ans:3,exp:"Schedules 2 & 6."},
{id:333,part:4,type:'mcq',q:"In the master-budget diagram, which three budgets flow directly out of the production budget into the cost of goods sold budget?",opts:["Direct material, direct manufacturing labour and manufacturing overhead cost budgets","R&D, marketing and distribution budgets","Cash, balance sheet and cash-flow budgets","Revenues, sales and profit budgets"],ans:0,exp:"Schedules 3, 4 and 5 feed Schedule 7."},
{id:334,part:4,type:'mcq',q:"In the master-budget diagram, the R&D/design, marketing and distribution budgets are all part of:",opts:["Schedule 3","Schedule 8 (nonmanufacturing costs)","Schedule 5","Schedule 7"],ans:1,exp:"Period costs budgeted in Schedule 8."},
{id:335,part:4,type:'mcq',q:"The budgeted income statement feeds into which part of the master budget?",opts:["The revenues budget","The production budget","The direct materials budget","The financial budget (cash budget and budgeted balance sheet)"],ans:3,exp:"The operating budget ends with the budgeted income statement, then the financial budget follows."},
{id:336,part:4,type:'tf',q:"The cost of goods sold budget applies to manufacturers only.",ans:true,exp:"As noted in the master budget diagram."},
{id:337,part:4,type:'mcq',q:"Which of the following is a component of the FINANCIAL budget in ACCT1102?",opts:["Production budget","Revenues budget","Cash budget","Direct labour budget"],ans:2,exp:"Also the budgeted balance sheet."},
{id:338,part:4,type:'mcq',q:"The most frequently used budget period is:",opts:["one year","one month","five years","one day"],ans:0,exp:"Definition given in the lecture."},
{id:339,part:4,type:'mcq',q:"The timeline for a budget depends on:",opts:["the number of employees","the auditor's preference","the motive for creating the budget","the tax year only"],ans:2,exp:"E.g. 6 months for a seasonal theatre production; 5 years for a new product line."},
{id:340,part:4,type:'mcq',q:"A rolling budget is:",opts:["a budget prepared only once","a budget always available for a specified future period, continually updated by adding a month, quarter or year to the period just ended","a budget for last year's actual results","a budget that ignores actual results"],ans:1,exp:"Definition given in the lecture."},
{id:341,part:4,type:'short',q:"A firm uses a 12-month rolling budget. At the end of March it completes the March budget period. What does it do next?",exp:"It adds April of next year to the budget so 12 months are always covered. A rolling budget is continually updated by adding a period (month) to the one just ended."},
{id:342,part:4,type:'tf',q:"A seasonal theatre production would typically need a five-year budget.",ans:false,exp:"The lecture example: 6 months for a seasonal theatre production; 5 years for the profitability of a new product line."},
{id:343,part:4,type:'mcq',q:"Revenue budget (sales budget) equals:",opts:["budgeted production x cost per unit","beginning inventory + purchases","budgeted unit sales x variable cost per unit","budgeted unit sales x budgeted selling price per unit"],ans:3,exp:"Schedule 1."},
{id:344,part:4,type:'mcq',q:"Budgeted units to be produced equals:",opts:["budgeted sales - desired ending inventory + beginning inventory","budgeted sales + beginning inventory + desired ending inventory","budgeted sales x desired ending inventory %","budgeted sales + desired ending finished goods inventory - expected beginning finished goods inventory"],ans:3,exp:"Schedule 2 (production budget in units)."},
{id:345,part:4,type:'table',q:"(ABC Window) New business, Year 1 budget. Unit sales: Q1 1,000; Q2 2,000; Q3 3,000; Q4 4,000. Price $1,000. Complete the sales budget revenue for each quarter and the full year.",exp:"Revenue: Q1 1,000,000; Q2 2,000,000; Q3 3,000,000; Q4 4,000,000; full year 10,000,000."},
{id:346,part:4,type:'table',q:"(ABC Window) Desired ending inventory = 10% of NEXT quarter's sales; Q1 Year 2 sales = 5,000 units; beginning FG for Q1 = 0. Complete the production budget (units to be produced) for Q1-Q4.",exp:"Ending FG: Q1 200, Q2 300, Q3 400, Q4 500. Units produced: Q1 1,200, Q2 2,100, Q3 3,100, Q4 4,100; full year 10,500."},
{id:347,part:4,type:'table',q:"Delta Bikes: unit sales Q1 800; Q2 1,000; Q3 1,200; Q4 1,500 (Q1 next year 900). Desired ending FG = 20% of next quarter's sales; opening FG at start of Q1 = 150 units. Complete the production budget.",exp:"Ending FG: 200, 240, 300, 180. Units produced: 850, 1,040, 1,260, 1,380; full year 4,530."},
{id:348,part:4,type:'calc',q:"Delta Bikes: complete the revenue budget (price $250 per bike) for Q1 800, Q2 1,000, Q3 1,200, Q4 1,500 units.",exp:"Revenue: 200,000; 250,000; 300,000; 375,000; full year 1,125,000."},
{id:349,part:4,type:'table',q:"Cafe Blend: sales Q1 2,000; Q2 2,400; Q3 3,000; Q4 2,600 (Q1 next year 2,200). Desired ending FG = 25% of next quarter's sales; beginning FG for Q1 = 500. Complete the production budget.",exp:"Ending FG: 600, 750, 650, 550. Units produced: 2,100, 2,550, 2,900, 2,500; full year 10,050."},
{id:350,part:4,type:'calc',q:"Cafe Blend: what is the total budgeted revenue for the year (price $40, 10,000 units)?",exp:"$400,000."},
{id:351,part:4,type:'calc',q:"A firm budgets sales of 6,000 units. Desired ending finished goods is 500 units and expected beginning finished goods is 800 units. How many units must be produced?",exp:"5,700 units."},
{id:352,part:4,type:'calc',q:"Production is 5,000 units; beginning finished goods 300; budgeted sales 4,800. What is the ending finished goods inventory?",exp:"500 units."},
{id:353,part:4,type:'calc',q:"Q2 sales are budgeted at 3,000 units and the firm wants ending FG equal to 15% of next quarter's sales. Q3 sales will be 4,000 units. Beginning Q2 inventory is 300. How many units to produce in Q2?",exp:"3,300 units."},
{id:354,part:4,type:'calc',q:"Budgeted unit sales are 900 in Q1 at $120 per unit and 1,100 in Q2 at $125 per unit. What is the revenue for the two quarters?",exp:"$245,500."},
{id:355,part:4,type:'mcq',q:"Why does the Q4 production budget for a full-year budget need Q1 sales of the following year?",opts:["Because desired ending inventory at the end of Q4 is a percentage of the next quarter's (Q1 of Year 2) sales","Because Q1 sales are the beginning inventory of Q4","Because production in Q4 is equal to next year's sales","Because revenue for Q4 is recorded in Q1"],ans:0,exp:"That is why the ABC Window data includes Q1 Year 2 sales."},
{id:356,part:4,type:'mcq',q:"In the full-year column of a production budget, the 'beginning finished goods' figure is:",opts:["the ending inventory of the last quarter","the beginning inventory of the FIRST quarter","the sum of all quarterly beginnings","zero always"],ans:1,exp:"The full-year column uses beginning Q1 and ending Q4 inventories."},
{id:357,part:4,type:'tf',q:"If sales are increasing each quarter and the firm holds a % of next quarter's sales as ending inventory, production in a quarter generally exceeds that quarter's sales.",ans:true,exp:"Ending inventory (based on higher next-quarter sales) exceeds beginning inventory, so production > sales."},
{id:358,part:4,type:'mcq',q:"Organisation structure is:",opts:["a list of the firm's shareholders","a schedule of costs","the master budget","an arrangement of lines of responsibility within an organisation"],ans:3,exp:"Organised by function, by product line/brand, or both."},
{id:359,part:4,type:'mcq',q:"A responsibility centre is:",opts:["a part, segment or subunit of an organisation whose manager is accountable for a specified set of activities","a department that only manages cash","the head office","a customer"],ans:0,exp:"Definition given in the lecture."},
{id:360,part:4,type:'mcq',q:"Responsibility accounting is:",opts:["a process of fixing blame for poor results","a system that measures the plans, budgets, actions and actual results of each responsibility centre","an arrangement of lines of authority","a way of examining changes to the plan"],ans:1,exp:"Definition given in the lecture."},
{id:361,part:4,type:'mcq',q:"(Quick Check 4) Which of the following is true of responsibility accounting?",opts:["It is a system that measures the plans, budgets, actions, and actual results of responsibility centers.","It is an arrangement of lines of responsibility and authority within a responsibility center.","It is a process of fixing blame for unexpected poor results.","It examines how a result will change if the original plan is not achieved."],ans:0,exp:"(b) describes organisation structure; (c) is wrong - focus on information, not blame."},
{id:362,part:4,type:'mcq',q:"A cost centre's manager is responsible for:",opts:["revenues only","revenues and costs","costs only","revenues, costs and investments"],ans:2,exp:"E.g. production or maintenance department."},
{id:363,part:4,type:'mcq',q:"A revenue centre's manager is responsible for:",opts:["costs only","revenues and costs","revenues only","revenues, costs and investments"],ans:2,exp:"E.g. the sales department."},
{id:364,part:4,type:'mcq',q:"A profit centre's manager is responsible for:",opts:["costs only","revenues only","revenues and costs","revenues, costs and investments"],ans:2,exp:"E.g. Hilton Sydney hotel."},
{id:365,part:4,type:'mcq',q:"An investment centre's manager is responsible for:",opts:["investments, revenues and costs","costs only","revenues only","revenues and costs only"],ans:0,exp:"E.g. a regional division of a multinational hotel chain."},
{id:366,part:4,type:'table',q:"Classify each as a cost, revenue, profit or investment centre: Production department; Sales department; An individual hotel branch (Hilton Sydney); Regional division of a multinational hotel chain; Maintenance department; A company-owned retail store; A subsidiary whose manager decides on capital investment.",exp:"Production dept: Cost. Sales dept: Revenue. Hilton Sydney: Profit. Regional division: Investment. Maintenance dept: Cost. Retail store: Profit. Subsidiary with capital investment authority: Investment."},
{id:367,part:4,type:'mcq',q:"The manager of a call centre is judged only on the cost of running the call centre. It is a:",opts:["revenue centre","cost centre","profit centre","investment centre"],ans:1,exp:"Costs only."},
{id:368,part:4,type:'mcq',q:"A regional manager who decides both on new hotels to build and their operations is heading a:",opts:["cost centre","revenue centre","profit centre","investment centre"],ans:3,exp:"Investment, revenue and cost responsibility."},
{id:369,part:4,type:'tf',q:"Every manager, regardless of level, is in charge of a responsibility centre.",ans:true,exp:"As per the lecture."},
{id:370,part:4,type:'tf',q:"A profit centre manager is responsible for both revenues and costs.",ans:true,exp:"As per the lecture."},
{id:371,part:4,type:'mcq',q:"Budgets coupled with responsibility accounting provide feedback in the form of:",opts:["fixed costs","audit opinions","tax adjustments","variances - actual results deviating from budgeted targets"],ans:3,exp:"Definition given in the lecture."},
{id:372,part:4,type:'short',q:"What do variances provide managers with?",exp:"Early warning of problems; a basis for performance evaluation; a basis for strategy evaluation."},
{id:373,part:4,type:'mcq',q:"Which is NOT a use of variances?",opts:["Early warning of problems","Guaranteeing that budget targets are always met","A basis for performance evaluation","A basis for strategy evaluation"],ans:1,exp:"Variances only identify deviations."},
{id:374,part:4,type:'mcq',q:"Controllability is:",opts:["the degree of influence a specific manager has over costs, revenues or related items for which he or she is responsible","the responsibility of the corporate controller","another word for responsibility","always clear-cut"],ans:0,exp:"Definition given in the lecture."},
{id:375,part:4,type:'mcq',q:"A controllable cost is:",opts:["any cost incurred in the centre","any fixed cost","any cost primarily subject to the influence of a given responsibility centre manager for a given period","any variable cost"],ans:2,exp:"Definition given in the lecture."},
{id:376,part:4,type:'mcq',q:"Responsibility accounting helps managers first focus on:",opts:["whom to blame for poor performance","whom to ask to obtain information, rather than whom to blame","whom to dismiss","whom to audit"],ans:1,exp:"Definition given in the lecture."},
{id:377,part:4,type:'tf',q:"Responsibility accounting focuses on gaining information and knowledge, not only on control, thereby enabling future improvement.",ans:true,exp:"As per the lecture."},
{id:378,part:4,type:'tf',q:"Performance reports for responsibility centres are sometimes designed to change managers' behaviour even if they decrease controllability.",ans:true,exp:"As per the lecture."},
{id:379,part:4,type:'mcq',q:"(Quick Check 6) Controllability",opts:["is always clear cut as to who has responsibility for a cost.","is another term for responsibility.","is the responsibility of the corporate controller.","is the degree of influence a specific manager has over costs, revenues, and other items."],ans:3,exp:"It is often NOT clear-cut and is not the same as responsibility."},
{id:380,part:4,type:'mcq',q:"Human factors in budgeting are important because budgeting:",opts:["is purely mechanical","is only done by accountants","does not affect staff","requires education, persuasion and intelligent interpretation, and affects preparers, users and those evaluated by the budget"],ans:3,exp:"Definition given in the lecture."},
{id:381,part:4,type:'mcq',q:"Budgetary slack (padding) is:",opts:["overestimating revenues and underestimating costs","the difference between two budgets","the time between budgets","underestimating budgeted revenues or overestimating budgeted costs to make targets easier to achieve"],ans:3,exp:"Definition given in the lecture."},
{id:382,part:4,type:'mcq',q:"Budgetary slack is a particular concern when budgets are used for:",opts:["cash forecasting only","tax reporting","performance evaluation","inventory valuation"],ans:2,exp:"As per the lecture."},
{id:383,part:4,type:'mcq',q:"Which is NOT a reason managers create budgetary slack?",opts:["To make sure the company's strategy is achieved with no risk","Their performance will look better if they exceed the budget","To cope with uncertainty","To guard against budget requests being cut back by senior management"],ans:0,exp:"The three real reasons are performance looks better, uncertainty, and guarding against cuts."},
{id:384,part:4,type:'mcq',q:"Stretch targets are:",opts:["challenging but achievable levels of expected performance, intended to create a little discomfort","easily achievable targets","impossible targets","targets set by auditors"],ans:0,exp:"Definition given in the lecture."},
{id:385,part:4,type:'mcq',q:"Kaizen budgeting sets targets that:",opts:["require the firm to stop budgeting","eliminate all inventory","require minor operational improvements to be found and successfully implemented","ignore the past"],ans:2,exp:"Definition given in the lecture."},
{id:386,part:4,type:'mcq',q:"(Quick Check 5) The major cost management concept used in Kaizen budgeting is that of",opts:["eliminating inventories of every type but materials.","refinements in the indirect-cost categories for costing systems.","continuous improvement.","sensitivity analysis using computer-based financial planning models."],ans:2,exp:"Kaizen = continuous improvement."},
{id:387,part:4,type:'mcq',q:"(Quick Check 7) Budgetary slack",opts:["is going to be included in budget estimates, so it should just be ignored.","provides managers with a hedge against unexpected circumstances.","should be totally eliminated from the budget.","is not found in governmental budgets."],ans:1,exp:"Managers use slack as a hedge against uncertainty; it isn't simply ignored and is also found in government budgets."},
{id:388,part:4,type:'short',q:"Explain budgetary slack, why managers create it, and two techniques to reduce it.",exp:"Slack = understating revenues / overstating costs so targets are easy to hit. Managers create it to look better when they beat budget, to cope with uncertainty and to protect against cuts from senior management. Techniques: stretch targets (challenging but achievable) and kaizen budgeting (targets requiring continuous small improvements)."},
{id:389,part:4,type:'calc',q:"A sales manager expects to sell 10,000 units but budgets only 8,500 units to make the target easy. What is the amount of budgetary slack in the revenue budget at $20 per unit?",exp:"$30,000. 1,500 units x $20."},
{id:390,part:4,type:'mcq',q:"A production manager submits a cost budget of $520,000 although the expected cost is $480,000. This is an example of:",opts:["a stretch target","budgetary slack (overestimating costs)","kaizen budgeting","a rolling budget"],ans:1,exp:"Overestimating costs makes the target easier to achieve."},
{id:391,part:4,type:'mcq',q:"A budget that requires a 2% cost reduction each quarter through small process improvements is best described as:",opts:["kaizen budgeting","budgetary slack","a master budget","a responsibility centre"],ans:0,exp:"Continuous improvement."},
{id:392,part:4,type:'tf',q:"Managers may build slack into their budgets because their performance will look better when they beat the budget.",ans:true,exp:"One of the three reasons given."},
{id:393,part:4,type:'mcq',q:"Which is the LAST budget in the operating budget of a manufacturer, before the financial budget begins?",opts:["The budgeted income statement","The revenues budget","The cash budget","The budgeted balance sheet"],ans:0,exp:"Operating budget ends with the budgeted income statement; the financial budget then follows."},
{id:394,part:4,type:'tf',q:"The master budget combines the operating budget and the financial budget.",ans:true,exp:"As per the lecture."},
{id:395,part:4,type:'calc',q:"Sales are budgeted at 1,000 units in Q1 and 2,000 units in Q2. Desired ending finished goods is 10% of next quarter's sales and beginning finished goods for Q1 is 100 units. How many units must be produced in Q1?",exp:"1,100 units."},
{id:396,part:4,type:'table',q:"What is each type of responsibility centre manager accountable for? Cost centre; Revenue centre; Profit centre; Investment centre.",exp:"Cost centre: Costs only. Revenue centre: Revenues only. Profit centre: Revenues and costs. Investment centre: Investments, revenues and costs."},
{id:397,part:4,type:'mcq',q:"A plant manager is evaluated on a cost that is an allocation of corporate-wide insurance which the manager cannot influence. Under the controllability concept this cost is:",opts:["fully controllable by the plant manager","a revenue item","not controllable by that manager, so it should not be the basis for evaluating the manager's performance (or should be reported separately)","an inventoriable cost of the plant only"],ans:2,exp:"Controllability is the degree of influence a specific manager has over the item."},
{id:398,part:4,type:'mcq',q:"In month 3 actual sales are well below budget, which prompts managers to investigate why. This illustrates that variances provide:",opts:["a guarantee of achieving the strategy","an early warning of problems","an audit opinion","a tax deduction"],ans:1,exp:"Variances give early warning, and a basis for performance and strategy evaluation."},
{id:399,part:4,type:'short',q:"Why should budgeting be integrated with an organisation's strategy? Use cost leadership and product differentiation as examples.",exp:"Budgets translate strategy into quantified plans. A cost leader (quality at a low price) will budget tight costs and volume-driven revenues; a differentiator (unique product at a higher price) will budget for R&D/marketing and premium prices. Without integration, budgets are just numbers unrelated to how the organisation creates value."},
{id:400,part:4,type:'short',q:"Describe the challenges in administering budgets and the human factors that must be managed.",exp:"Challenges: the process is time-consuming - senior managers spend about 10-20% of their time and finance planning departments up to 50%; the annual process can take months and consumes many resources. Human factors: budgets affect those who prepare them, use them for decisions and are evaluated by them; they require education, persuasion and interpretation, and can create budgetary slack, so stretch targets and kaizen budgeting may be needed."},
];
